async function nativeStartGuard(){const kind=nativeClientKind();if(!kind)return true;const key='nahIsoNativeStartGuardV7:'+kind;let seen=false;try{seen=sessionStorage.getItem(key)==='1'}catch(_e){}if(seen)return true;let res,payload=null;try{const url=restBase()+'auth/client-start?nah_client_start=1';res=await fetch(url,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json','Content-Type':'text/plain;charset=UTF-8'},body:'{}'});try{payload=await res.json()}catch(_e){}}catch(_e){throw new Error('Không thể kết nối máy chủ xác thực ứng dụng. Vui lòng kiểm tra kết nối mạng và thử lại.')}if(!res.ok||payload?.clientKind!==kind)throw new Error(payload?.message||'Không thể xác nhận phiên ứng dụng. Vui lòng thử lại.');if(kind==='desktop'){if(payload?.freshLoginRequired!==false||!['online-validated-device','persistent-device'].includes(payload?.sessionPolicy))throw new Error('Không thể xác lập phiên Desktop. Vui lòng kiểm tra kết nối mạng và mở lại ứng dụng.')}else if(kind==='android'){if(payload?.freshLoginRequired!==false||payload?.sessionPolicy!=='persistent')throw new Error('Không thể xác lập phiên Android cá nhân. Vui lòng mở lại ứng dụng.')}try{sessionStorage.setItem(key,'1')}catch(_e){}return true}
