async function renderDrawerTab(r){const box=$('#drawerTabBody');$$('[data-dtab]').forEach(b=>b.classList.toggle('active',b.dataset.dtab===state.drawerTab));if(r.module==='certprogress'&&state.drawerTab==='info'){box.innerHTML=certProgressInfoHtml(r);wireCertProgressInfo(r);return}if(r.module==='certprogress'&&state.drawerTab==='checklist'){box.innerHTML='<div class="loading">Đang tải danh mục…</div>';try{box.innerHTML=await certProgressChecklistHtml(r);wireCertProgressChecklist(r)}catch(e){box.innerHTML=`<div class="note">${esc(e.message)}</div>`}return}if((r.module==='documents'||r.module==='forms')&&['versions','workflow','distribution','reading','history'].includes(state.drawerTab)){await renderDocumentTab(r);return}if(state.drawerTab==='qms'){await renderQmsTab(r);return}if(state.drawerTab==='info'){box.innerHTML=r.module==='iso'?isoRequirementInfoHtml(r):recordInfoHtml(r.module,r);wireRecordForm(r.module,r);return}if(state.drawerTab==='assign'){box.innerHTML=assignmentHtml(r);wireAssignment(r);return}if(state.drawerTab==='progress'){box.innerHTML='<div class="loading">Đang tải tiến độ…</div>';try{box.innerHTML=await progressReportHtml(r);wireProgressReport(r)}catch(e){box.innerHTML=`<div class="note">${esc(e.message)}</div>`}return}if(state.drawerTab==='chat'){box.innerHTML=commentsHtml(r);wireComments(r);return}if(state.drawerTab==='evidence'){box.innerHTML=evidenceHtml(r);wireEvidence(r);return}if(state.drawerTab==='history'){box.innerHTML=activityHtml(r);return}if(r.module==='iso'&&['guidance','handbook','forms'].includes(state.drawerTab)){box.innerHTML='<div class="loading">Đang tải hướng dẫn…</div>';try{const ctx=await loadIsoContext(r);if(state.drawerTab==='forms'){await renderIsoFormsTab(r,ctx);return}box.innerHTML=state.drawerTab==='guidance'?isoGuidanceHtml(ctx):isoHandbookHtml(ctx)}catch(e){box.innerHTML=`<div class="note">${esc(e.message)}</div>`};return}box.innerHTML=evidenceHtml(r);wireEvidence(r)}
async function renderIsoFormsTab(r,ctx){const box=$('#drawerTabBody'),records=await api('records?module=isoforms');box.innerHTML=isoFormsHubHtml(ctx,r,records||[]);const hub=ctx.formHub||{},all=[...(hub.iso_templates||[]).map(t=>({...t,_sourceKind:'iso'})),...(hub.reused_qd2429_templates||[]).map(t=>({...t,_sourceKind:'qd2429'}))],byId=Object.fromEntries(all.map(t=>[t.id,t]));const openEditor=async(t,record=null)=>{let rec=record||{};if(rec.id)rec=await api(`records/${rec.id}`);openDrawer(`${t.id} · ${t.title}`,'iso',isoFormRecordEditorHtml(t,rec,t._sourceKind||'iso',ctx.clause),{layout:'modal'});$$('[data-close]',$('#drawerBody')).forEach(b=>b.onclick=closeDrawer);const form=$('#isoFormRecord');form?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form),fields={};for(const field of isoFormFields(t)){const key='qf_'+field.name;fields[field.name]=field.type==='checkbox'?(fd.get(key)?'1':''):String(fd.get(key)||'').trim()}const clauses=isoFormTemplateClauses(t).length?isoFormTemplateClauses(t):[ctx.clause];const payload={module:'isoforms',code:rec.code||`${t.id}-${String(Date.now()).slice(-8)}`,title:t.title,description:String(fd.get('description')||''),status:String(fd.get('status')||'in_progress'),priority:String(fd.get('priority')||'normal'),due_date:String(fd.get('due_date')||''),owner_ref:String(fd.get('owner_ref')||''),progress:rec.progress||0,data:{record_type:'iso_form_record',framework:'TCVN ISO 15189:2025',template_id:t.id,template_source:t._sourceKind||'iso',clauses,form_fields:fields,source_requirement_id:r.id}};try{const saved=rec.id?await api(`records/${rec.id}`,{method:'PATCH',json:payload}):await api('records',{method:'POST',json:payload});toast(rec.id?'Đã cập nhật bản ghi':'Đã tạo bản ghi ISO');if(!rec.id){closeDrawer();await refreshDrawer(r.id);state.drawerTab='forms';await renderDrawerTab(state.current)}else{closeDrawer();await refreshDrawer(r.id);state.drawerTab='forms';await renderDrawerTab(state.current)}}catch(err){toast(err.message,'err')}});if(rec.id){$('#isoPrintRecord')?.addEventListener('click',()=>{auditUiEvent('print_a4',{module:'isoforms',record_id:rec.id,template_id:t.id,title:t.title,format:'print'});withExportHtml(isoFormRecordA4(t,rec,ctx.clause),el=>printElementA4(el))});$('#isoPdfRecord')?.addEventListener('click',()=>withExportHtml(isoFormRecordA4(t,rec,ctx.clause),el=>exportElementPdf(el,`${safeFileName(rec.code||t.id)}.pdf`,{action:'record_export',module:'isoforms',record_id:rec.id,template_id:t.id,title:t.title})));$('#isoDocxRecord')?.addEventListener('click',()=>withExportHtml(isoFormRecordA4(t,rec,ctx.clause),el=>exportElementDocx(el,`${safeFileName(rec.code||t.id)}.docx`,t.title,{action:'record_export',module:'isoforms',record_id:rec.id,template_id:t.id,title:t.title})));wireEvidence(rec)}};$$('[data-isoform-new]').forEach(b=>b.onclick=()=>{const t=byId[b.dataset.isoformNew];if(t)openEditor(t)});$$('[data-isoform-template]').forEach(b=>b.onclick=()=>{const t=byId[b.dataset.isoformTemplate];if(t)openFormTemplate(t)});$$('[data-isoform-record]').forEach(row=>row.onclick=()=>{const rec=(records||[]).find(x=>+x.id===+row.dataset.isoformRecord);if(!rec)return;const t=byId[rec.data?.template_id]||{id:rec.data?.template_id||'',title:rec.title,clauses:rec.data?.clauses||[ctx.clause],fields:[]};t._sourceKind=rec.data?.template_source||'iso';openEditor(t,rec)});$$('[data-isoforms-report]').forEach(b=>b.onclick=()=>{const def=(hub.reports||[]).find(x=>x.id===b.dataset.isoformsReport)||{};const html=isoClauseFormsReportA4(ctx.clause,ctx,records||[],def.title||'Báo cáo hồ sơ và biểu mẫu ISO');openDrawer(def.title||'Báo cáo ISO','iso',`<div class="export-toolbar"><button class="btn" id="isoHubPrint">In A4</button><button class="btn" id="isoHubPdf">PDF A4</button><button class="btn primary" id="isoHubDocx">DOCX A4</button></div><div id="isoHubReport">${html}</div>`,{layout:'modal'});$('#isoHubPrint')?.addEventListener('click',()=>printElementA4($('#isoHubReport').firstElementChild));$('#isoHubPdf')?.addEventListener('click',()=>exportElementPdf($('#isoHubReport').firstElementChild,`${safeFileName(def.title||'Bao-cao-ISO')}-${safeFileName(ctx.clause)}.pdf`,{action:'report_export',module:'isoforms',title:def.title||'Báo cáo ISO',period:ctx.clause}));$('#isoHubDocx')?.addEventListener('click',()=>exportElementDocx($('#isoHubReport').firstElementChild,`${safeFileName(def.title||'Bao-cao-ISO')}-${safeFileName(ctx.clause)}.docx`,def.title||'Báo cáo ISO',{action:'report_export',module:'isoforms',title:def.title||'Báo cáo ISO',period:ctx.clause}))})}
function printElementA4(el){if(!el)return;const frame=document.createElement('iframe');frame.setAttribute('aria-hidden','true');frame.style.cssText='position:fixed;width:1px;height:1px;right:0;bottom:0;border:0;opacity:0;pointer-events:none';document.body.appendChild(frame);const doc=frame.contentDocument||frame.contentWindow.document;doc.open();doc.write(`<!doctype html><html><head><meta charset="utf-8"><title>NAH LAB SUITE</title><style>@page{size:A4;margin:12mm}html,body{margin:0;padding:0;background:#fff;color:#111}body{font-family:Arial,"Noto Sans","Segoe UI",sans-serif}*{box-sizing:border-box}article{width:100%;max-width:186mm;margin:0 auto}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #777;padding:6px;font-size:11px;vertical-align:top;overflow-wrap:anywhere;white-space:normal}tr,.form-signatures,section{break-inside:avoid;page-break-inside:avoid}h1{font-size:19px;line-height:1.3;text-align:center}h2{font-size:16px}h3{font-size:14px}p,li{font-size:11px;line-height:1.45}.iso-form-header{display:flex;justify-content:space-between;gap:16px;border-bottom:2px solid #222;padding-bottom:10px;margin-bottom:14px}.iso-form-header span,.iso-form-header strong{display:block}.iso-form-control{font-size:10px;line-height:1.55;text-align:right}.form-signatures{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;text-align:center;margin-top:28px;min-height:90px}.internal-note,.governance-note,[data-internal-audit],button,.btn,.export-toolbar{display:none!important}.iso-form-footer{display:flex;justify-content:flex-end;margin-top:12px;padding-top:7px;border-top:1px solid #aaa;font-size:9.5px;color:#444}</style></head><body>${el.outerHTML}</body></html>`);doc.close();const cleanup=()=>setTimeout(()=>frame.remove(),400);setTimeout(()=>{try{frame.contentWindow.focus();frame.contentWindow.print();frame.contentWindow.onafterprint=cleanup;setTimeout(cleanup,3000)}catch(e){frame.remove();toast('Không thể mở hộp thoại in A4.','err')}},200)}
function wireRecordForm(module,r={}){const f=$('#recordForm');$$('[data-close]',f).forEach(b=>b.onclick=closeDrawer);f.onsubmit=async e=>{e.preventDefault();try{const data=collectForm(module,f);const saved=r.id?await api(`records/${r.id}`,{method:'PATCH',json:data}):await api('records',{method:'POST',json:data});toast(r.id?'Đã cập nhật':'Đã tạo bản ghi');if(r.id){state.current=saved;await refreshDrawer(saved.id)}else{closeDrawer();await render()}}catch(err){toast(err.message,'err')}};$('#printRecord')?.addEventListener('click',()=>printRecord(r));$('#pdfRecord')?.addEventListener('click',()=>withExportHtml(recordA4Html(r),el=>exportElementPdf(el,`${safeFileName(r.code||r.title)}.pdf`,{action:'record_export',module:r.module,record_id:r.id,title:r.title})));$('#docxRecord')?.addEventListener('click',()=>withExportHtml(recordA4Html(r),el=>exportElementDocx(el,`${safeFileName(r.code||r.title)}.docx`,r.title,{action:'record_export',module:r.module,record_id:r.id,title:r.title})))}
function assignmentHtml(r){const list=(r.assignments||[]).map(a=>`<div class="assignment"><div><strong>${esc(a.assignee_name)}</strong><div class="meta">${esc(a.assignee_role)} · ${a.assignment_role==='lead'?'Đầu mối':'Thành viên'}${a.due_date?' · Hạn '+fmtDate(a.due_date):''}</div></div>${hasCap('assign_tasks')?`<button class="btn small danger" data-unassign="${a.id}">Xóa</button>`:''}</div>`).join('')||'<div class="note">Chưa phân công thành viên. Có thể chỉ định một người làm đầu mối và thêm các thành viên phối hợp.</div>';let form='';if(hasCap('assign_tasks')&&(state.boot.assignableUsers||[]).length){form=`<div class="section-title">Thêm phân công</div><form id="assignmentForm"><div class="form-grid"><div class="field"><label>Người nhận</label><select name="assignee_ref" required><option value="">Chọn tài khoản</option>${state.boot.assignableUsers.map(u=>`<option value="${esc(u.ref)}">${esc(u.name)} — ${esc(u.roleLabel)}</option>`).join('')}</select></div><div class="field"><label>Vai trò</label><select name="assignment_role"><option value="lead">Đầu mối phụ trách</option><option value="member">Thành viên phối hợp</option></select></div><div class="field"><label>Thời hạn</label><input type="date" name="due_date" value="${esc(r.due_date||'')}"></div></div><div class="form-actions"><button class="btn primary" type="submit">Giao nhiệm vụ</button></div></form>`}return `<div class="section-title">Danh sách phân công</div><div class="assignment-list">${list}</div>${form}`}
function wireAssignment(r){$('#assignmentForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await api(`records/${r.id}/assignments`,{method:'POST',json:Object.fromEntries(fd.entries())});toast('Đã giao nhiệm vụ');await refreshDrawer(r.id);await refreshBootstrapLight()}catch(err){toast(err.message,'err')}});$$('[data-unassign]').forEach(b=>b.onclick=async()=>{if(!confirm('Hủy phân công này?'))return;try{await api(`assignments/${b.dataset.unassign}`,{method:'DELETE'});toast('Đã hủy phân công');await refreshDrawer(r.id)}catch(err){toast(err.message,'err')}})}
async function progressReportHtml(r){const rows=await api(`records/${r.id}/progress-reports`);const history=(rows||[]).map(x=>`<article class="progress-update-card"><div class="progress-update-head"><div><strong>${esc(x.user_name||'Người dùng')}</strong><span>${esc(x.created_at||'')}</span></div><div><b>${x.progress}%</b><span class="badge ${esc(x.status||'in_progress')}">${esc(statusLabels[x.status]||x.status||'Đang thực hiện')}</span></div></div>${x.work_done?`<div><small>Đã thực hiện</small><p>${esc(x.work_done)}</p></div>`:''}${x.blocker?`<div class="progress-warning"><small>Khó khăn / vướng mắc</small><p>${esc(x.blocker)}</p></div>`:''}${x.support_request?`<div class="progress-support"><small>Đề nghị hỗ trợ</small><p>${esc(x.support_request)}</p></div>`:''}${x.next_action?`<div><small>Bước tiếp theo</small><p>${esc(x.next_action)}</p></div>`:''}</article>`).join('')||'<div class="note">Chưa có cập nhật tiến độ.</div>';return `<div class="progress-report-layout"><section><div class="section-title">Cập nhật mới</div><form id="progressReportForm"><div class="form-grid"><div class="field"><label>Tiến độ hiện tại (%)</label><input type="number" min="0" max="100" name="progress" value="${esc(r.progress??0)}"></div><div class="field"><label>Trạng thái</label><select name="status"><option value="in_progress" ${r.status==='in_progress'?'selected':''}>Đang thực hiện</option><option value="review" ${r.status==='review'?'selected':''}>Chờ rà soát</option><option value="done" ${['done','closed','approved'].includes(r.status)?'selected':''}>Hoàn thành</option></select></div><div class="field full"><label>Đã thực hiện</label><textarea name="work_done" placeholder="Nội dung đã hoàn thành hoặc đã cập nhật…"></textarea></div><div class="field full"><label>Khó khăn / vướng mắc</label><textarea name="blocker" placeholder="Nêu rõ điểm đang vướng nếu có…"></textarea></div><div class="field full"><label>Đề nghị hỗ trợ</label><textarea name="support_request" placeholder="Nội dung cần Trưởng khoa hoặc đơn vị liên quan hỗ trợ…"></textarea></div><div class="field full"><label>Bước tiếp theo</label><textarea name="next_action" placeholder="Việc dự kiến thực hiện tiếp theo…"></textarea></div></div><div class="form-actions"><button class="btn primary">Lưu cập nhật</button></div></form></section><section><div class="section-title">Lịch sử cập nhật</div><div class="progress-update-list">${history}</div></section></div>`}
