function humanSize(n){if(n===null||n===undefined)return'—';const u=['B','KB','MB','GB'];let i=0,v=+n||0;while(v>=1024&&i<u.length-1){v/=1024;i++}return `${v>=10||i===0?Math.round(v):v.toFixed(1)} ${u[i]}`}
async function renderDriveFiles(recentFile=null){let data;try{data=await api(`drive/files?ts=${Date.now()}`,{cache:'no-store'})}catch(e){$('#content').innerHTML=`<div class="card empty"><strong>Google Drive hiện chưa khả dụng.</strong><div class="panel-sub">${esc(e.message||'Không thể xác thực kết nối Google Drive.')}</div>${state.boot.user.isWpAdmin?'<button class="btn small" id="driveOpenSettings">Mở Cài đặt Google Drive</button>':''}</div>`;$('#driveOpenSettings')?.addEventListener('click',()=>go('settings'));return}let files=[...(data.files||[])];if(recentFile?.id&&!files.some(f=>String(f.id)===String(recentFile.id)))files=[{...recentFile,_recent:true},...files];const rows=files.map(f=>`<tr><td><strong>${esc(f.name)}</strong>${f._recent?'<span class="badge" style="margin-left:7px">Vừa tải lên</span>':''}<div class="meta">${esc(f.mimeType||'')}</div></td><td>${humanSize(f.size)}</td><td>${f.modifiedTime?esc(new Date(f.modifiedTime).toLocaleString('vi-VN')):'—'}</td><td>${f.mimeType==='application/vnd.google-apps.folder'?'<span class="badge">Thư mục</span>':`<a class="btn small" href="${esc(f.appUrl)}" target="_blank" rel="noopener">Xem tệp</a>`}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Thư mục Google Drive chưa có tệp.</td></tr>';$('#content').innerHTML=`<div class="toolbar"><div><strong>Kho Google Drive</strong><div class="panel-sub">Tài liệu và hồ sơ dùng chung của Khoa Xét nghiệm.</div></div>${hasCap('upload')?'<form id="driveQuickUpload" style="display:flex;gap:7px;align-items:center"><input type="file" name="file" required><button class="btn primary small">Tải lên</button></form>':''}</div><div class="card table-card"><table class="data-table"><thead><tr><th>TỆP</th><th>DUNG LƯỢNG</th><th>CẬP NHẬT</th><th>THAO TÁC</th></tr></thead><tbody>${rows}</tbody></table></div>`;$('#driveQuickUpload')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const file=form.file.files[0];if(!file)return;const btn=form.querySelector('button');if(btn)btn.disabled=true;const fd=new FormData();fd.append('file',file);try{const result=await api('drive/files',{method:'POST',body:fd});if(!result?.uploaded||!result?.confirmed||!result?.file?.id)throw new Error('Google Drive chưa xác nhận tệp sau khi tải lên.');toast('Đã lưu tệp lên Google Drive');await new Promise(r=>setTimeout(r,250));await renderDriveFiles(result.file)}catch(err){toast(err.message,'err');if(btn)btn.disabled=false}})}
function uniqueTextItems(items){const seen=new Set(),out=[];for(const x of (items||[])){const k=String(x||'').trim().toLocaleLowerCase('vi-VN').replace(/\s+/g,' ');if(!k||seen.has(k))continue;seen.add(k);out.push(x)}return out}
function listHtml(items){return `<ul>${uniqueTextItems(items).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`}
function summaryCardsHtml(cards,klass='overview-cards'){return cards&&cards.length?`<div class="${klass}">${cards.map(c=>`<div class="summary-card"><small>${esc(c.label||'')}</small><strong>${esc(c.value??'0')}</strong><span>${esc(c.unit||'')}</span></div>`).join('')}</div>`:''}
function progressGroupRows(groups){return (groups||[]).map(g=>`<tr><td><strong>${esc(g.name||'')}</strong><div class="meta">${esc((g.assignees||[]).join(', ')||'Chưa phân công')}</div></td><td>${g.assigned_date?fmtDate(g.assigned_date):'—'}</td><td>${g.revised_due?fmtDate(g.revised_due):'—'}</td><td><span class="badge ${esc(g.status||'review')}">${esc(g.status_label||statusLabels[g.status]||'Đang theo dõi')}</span></td><td>${esc(g.reviewer||'—')}</td><td>${esc(g.note||'')}</td></tr>`).join('')}

function sourceRows(items=[]){
 const files=(Array.isArray(items)?items:[]).filter(x=>x&&!x.isFolder);
 return files.map(x=>{
  const clauses=Array.isArray(x.clauses)?x.clauses.filter(Boolean):[];
  const clauseText=clauses.length?clauses.join(', '):'—';
  const category=String(x.category||'Tài liệu nguồn');
  const path=String(x.path||x.name||'');
  const hay=[x.name,path,category,clauseText].join(' ').toLowerCase();
  const href=x.appUrl||x.webViewLink||'';
  const open=href?`<a class="btn small" href="${esc(href)}" target="_blank" rel="noopener">Mở</a>`:'<span class="meta">—</span>';
  return `<tr data-source-row data-hay="${esc(hay)}"><td><strong>${esc(x.name||'Tài liệu')}</strong><small class="source-path">${esc(path)}</small></td><td>${esc(category)}</td><td>${esc(clauseText)}</td><td>${open}</td></tr>`;
 }).join('')
}

