function handbookChapterHtml(ch){const t=ch.section_titles||{};return `<div class="knowledge-detail applied-learning"><div class="clause-row">${(ch.clauses||[]).map(c=>`<span class="clause-chip">${esc(c)}</span>`).join('')}</div><section><h4>${esc(t.intro||ch.title)}</h4><p class="lead content-core">${esc(ch.summary||'')}</p></section>${ch.plain_language?`<section class="plain-language-box"><h4>Hiểu đơn giản</h4><p>${esc(ch.plain_language)}</p></section>`:''}<section><h4>${esc(t.why||'Ý nghĩa trong thực hành')}</h4><p>${esc(ch.why||'')}</p></section><section><h4>${esc(t.principles||'Điểm cần nắm')}</h4>${listHtml(ch.principles)}</section>${ch.decision_steps?.length?`<section class="practice-box"><h4>Cách ra quyết định từng bước</h4><ol>${ch.decision_steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>`:''}<section><h4>${esc(t.steps||'Cách thực hiện')}</h4><ol>${(ch.steps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><section class="case-box"><h4>${esc(t.example||'Tình huống thực hành')}</h4><p>${esc(ch.example||'')}</p></section><div class="context-columns"><section class="attention-box"><h4>${semanticSvg('warning')}<span>${esc((t.errors==='Lưu ý và Thận trọng'?'Sai lầm thường gặp':t.errors)||'Sai lầm thường gặp')}</span></h4>${listHtml(uniqueTextItems([...(ch.common_errors||[]),...(ch.cautions||[])]))}</section><section class="evidence-box"><h4>${esc(t.evidence||'Hồ sơ liên quan')}</h4>${listHtml(ch.evidence)}</section></div><section><h4>${esc(t.forms||'Biểu mẫu liên quan')}</h4>${listHtml(ch.forms)}</section><section class="self-check"><h4>${esc(t.checklist||'Gợi ý áp dụng tại đơn vị')}</h4>${listHtml(ch.checklist)}</section>${ch.reference_note?`<section class="reference-note"><h4>Căn cứ áp dụng và phạm vi tham khảo</h4><p>${esc(ch.reference_note)}</p></section>`:''}<section><h4>${esc(t.sources||'Tài liệu tham khảo')}</h4><div class="source-tags">${(ch.sources||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div></section></div>`}
function qd2429FieldControl(field,value=''){const req=field.required?' required':'';const v=value??'';const name=esc(field.name||'field');const ph=field.placeholder?` placeholder="${esc(field.placeholder)}"`:'';if(field.type==='textarea')return `<textarea name="qf_${name}"${req}${ph}>${esc(v)}</textarea>`;if(field.type==='select')return `<select name="qf_${name}"${req}><option value="">— Chọn —</option>${(field.options||[]).map(o=>`<option value="${esc(o)}" ${String(v)===String(o)?'selected':''}>${esc(o)}</option>`).join('')}</select>`;if(field.type==='checkbox')return `<label class="pa-check"><input type="checkbox" name="qf_${name}" value="1" ${v?'checked':''}> ${esc(field.label||'')}</label>`;return `<input type="${esc(field.type||'text')}" name="qf_${name}" value="${esc(v)}"${req}${ph}>`}
