async function renderQD2429(){
 const [d,assessment,qdRecordsAll]=await Promise.all([api('knowledge/qd2429'),api('knowledge/qd2429/assessment'),api('records?module=qd2429')]);
 const chapters=d.chapters||[], handbook=d.handbook||[], levels=d.quality_levels||[], criteria=assessment.criteria||d.criteria||[];
 const formHub=d.form_hub||{}, qdTemplates=formHub.new_templates||[], reusedFormMap=formHub.reused_iso_forms||[], reportDefs=formHub.reports||[], sharedIsoForms=d.shared_iso_forms||[];
 const qdFormRecords=(qdRecordsAll||[]).filter(r=>r.data?.record_type==='qd2429_form_record');
 const qdTemplateById=Object.fromEntries(qdTemplates.map(t=>[t.id,t]));
 const arows=assessment.chapters||[];
 const totals=assessment.totals||{criteria:criteria.length,assessed:0,achieved_points:0,applicable_max_points:268,normative_max_points:268,percent:0,mandatory_one_star_ok:false,mandatory_three_star_ok:false};
 const percent=Number(totals.percent||0),oneOk=!!totals.mandatory_one_star_ok,threeOk=!!totals.mandatory_three_star_ok;
 const qualityLevel=()=>{if(!totals.complete)return 'Đang tự đánh giá';if(percent<20||!oneOk)return 'Chưa xếp mức';if(percent<35)return 'Mức 1';if(percent<65)return 'Mức 2';if(!threeOk)return 'Chưa xếp mức';if(percent<85)return 'Mức 3';if(percent<95)return 'Mức 4';return 'Mức 5'};
 const level=qualityLevel();
 const formsForCriterion=(code)=>{const own=qdTemplates.filter(t=>(t.criteria_refs||[]).includes(code));const sharedIds=reusedFormMap.filter(m=>(m.criteria_refs||[]).includes(code)).map(m=>m.id);const shared=sharedIsoForms.filter(t=>sharedIds.includes(t.id));return {own,shared,total:own.length+shared.length}};
 const reusedIsoForms=reusedFormMap.map(m=>{const t=sharedIsoForms.find(x=>x.id===m.id)||{};return {...t,_qd:m}}).filter(x=>x.id);
 const openQdFormRecord=async(t,record=null)=>{let r=record||{};if(r.id)r=await api(`records/${r.id}`);openDrawer(`${t.id} · ${t.title}`,'qd2429',qd2429FormRecordEditorHtml(t,r),{layout:'modal'});$$('[data-close]',$('#drawerBody')).forEach(b=>b.onclick=closeDrawer);const form=$('#qd2429FormRecord');form?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form),fields={};for(const field of (t.fields||[])){const key='qf_'+field.name;fields[field.name]=field.type==='checkbox'?(fd.get(key)?'1':''):String(fd.get(key)||'').trim()}const payload={module:'qd2429',code:r.code||`${t.id}-${String(Date.now()).slice(-8)}`,title:t.title,description:String(fd.get('description')||''),status:String(fd.get('status')||'in_progress'),priority:String(fd.get('priority')||'normal'),due_date:String(fd.get('due_date')||''),owner_ref:String(fd.get('owner_ref')||''),progress:r.progress||0,data:{record_type:'qd2429_form_record',framework:'QĐ 2429/QĐ-BYT',template_id:t.id,chapter:t.chapter,criteria_refs:t.criteria_refs||[],category:t.category||'',form_fields:fields}};try{const saved=r.id?await api(`records/${r.id}`,{method:'PATCH',json:payload}):await api('records',{method:'POST',json:payload});const idx=qdFormRecords.findIndex(x=>+x.id===+saved.id);if(idx>=0)qdFormRecords[idx]=saved;else qdFormRecords.unshift(saved);toast(r.id?'Đã cập nhật bản ghi':'Đã tạo bản ghi QĐ 2429');closeDrawer();show('forms')}catch(err){toast(err.message,'err')}});if(r.id){$('#qdPrintRecord')?.addEventListener('click',()=>{auditUiEvent('print_a4',{module:'qd2429',record_id:r.id,template_id:t.id,title:t.title,format:'print'});const old=$('#content').innerHTML;$('#content').innerHTML=qd2429FormRecordA4(t,r);window.print();$('#content').innerHTML=old;renderQD2429()});$('#qdPdfRecord')?.addEventListener('click',()=>withExportHtml(qd2429FormRecordA4(t,r),el=>exportElementPdf(el,`${safeFileName(r.code||t.id)}.pdf`,{action:'record_export',module:'qd2429',record_id:r.id,template_id:t.id,title:t.title})));$('#qdDocxRecord')?.addEventListener('click',()=>withExportHtml(qd2429FormRecordA4(t,r),el=>exportElementDocx(el,`${safeFileName(r.code||t.id)}.docx`,t.title,{action:'record_export',module:'qd2429',record_id:r.id,template_id:t.id,title:t.title})));wireEvidence(r)}};
 const qdReportHtml=(def)=>{const head=`<div class="report-head"><div class="report-brand"><img src="${esc(cfg.logoUrl||'')}" alt="NAH"><div><h2>${esc(def.title)}</h2><div class="report-meta">Bệnh viện Hữu nghị Đa khoa Nghệ An - Giai đoạn 2 · Khoa Xét nghiệm</div></div></div><div class="report-meta">QĐ 2429/QĐ-BYT · Kỳ ${esc(assessment.period||'')}</div></div>`;let content='';if(def.type==='assessment_overview'){content=`<div class="qd2429-report-kpis"><div><b>${totals.assessed||0}/169</b><span>tiêu chí đã đánh giá</span></div><div><b>${Number(totals.achieved_points||0).toFixed(1).replace('.0','')}/${Number(totals.applicable_max_points||268).toFixed(1).replace('.0','')}</b><span>điểm áp dụng</span></div><div><b>${percent}%</b><span>tỷ lệ</span></div><div><b>${esc(level)}</b><span>mức chất lượng</span></div></div><table class="data-table"><thead><tr><th>CHƯƠNG</th><th>ĐÁNH GIÁ</th><th>ĐIỂM</th><th>TỶ LỆ</th></tr></thead><tbody>${arows.map(x=>`<tr><td><b>${x.number}. ${esc(x.title)}</b></td><td>${x.assessed}/${x.criteria_count}</td><td>${Number(x.achieved_points||0).toFixed(1).replace('.0','')}/${Number(x.applicable_max_points||x.max_points||0).toFixed(1).replace('.0','')}</td><td>${Number(x.percent||0)}%</td></tr>`).join('')}</tbody></table>`}else if(def.type==='mandatory'){const rows=criteria.filter(c=>c.mandatory_marker).map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.mandatory_marker)}</td><td>${esc(c.title)}</td><td>${esc(resultLabel[c.result]||c.result)}</td><td>${esc(c.note||'')}</td></tr>`).join('');content=`<table class="data-table"><thead><tr><th>MÃ</th><th>DẤU</th><th>TIÊU CHÍ</th><th>KẾT QUẢ</th><th>GHI CHÚ</th></tr></thead><tbody>${rows}</tbody></table>`}else if(def.type==='gaps'){const rows=criteria.filter(c=>['unassessed','partial','fail'].includes(c.result)).map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.title)}</td><td>${esc(resultLabel[c.result]||c.result)}</td><td>${esc(c.note||'')}</td><td>${c.evidence_url?esc(c.evidence_url):'—'}</td></tr>`).join('');content=`<table class="data-table"><thead><tr><th>MÃ</th><th>TIÊU CHÍ</th><th>KẾT QUẢ</th><th>GHI CHÚ/HÀNH ĐỘNG</th><th>MINH CHỨNG</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Không còn khoảng trống thuộc bộ lọc.</td></tr>'}</tbody></table>`}else if(def.type==='form_register'||def.type==='overdue'){const today=new Date().toISOString().slice(0,10);const rows0=def.type==='overdue'?qdFormRecords.filter(r=>r.due_date&&r.due_date<today&&!['done','closed','approved'].includes(r.status)):qdFormRecords;content=`<table class="data-table"><thead><tr><th>MÃ</th><th>BIỂU MẪU/HỒ SƠ</th><th>CHƯƠNG</th><th>PHỤ TRÁCH</th><th>HẠN</th><th>TRẠNG THÁI</th></tr></thead><tbody>${rows0.map(r=>`<tr><td>${esc(r.code||'#'+r.id)}</td><td>${esc(r.title)}</td><td>${esc(r.data?.chapter||'—')}</td><td>${esc(r.owner_name||r.owner_ref||'—')}</td><td>${fmtDate(r.due_date)}</td><td>${esc(statusLabels[r.status]||r.status)}</td></tr>`).join('')||'<tr><td colspan="6">Chưa có bản ghi phù hợp.</td></tr>'}</tbody></table>`}else if(def.type==='evidence'){const linked=criteria.filter(c=>c.evidence_url);content=`<h3>Minh chứng liên kết trong Tự đánh giá</h3><table class="data-table"><thead><tr><th>MÃ</th><th>TIÊU CHÍ</th><th>LIÊN KẾT</th></tr></thead><tbody>${linked.map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.title)}</td><td>${esc(c.evidence_url)}</td></tr>`).join('')||'<tr><td colspan="3">Chưa có liên kết minh chứng.</td></tr>'}</tbody></table><p class="note">Các tệp minh chứng tải trực tiếp vào bản ghi biểu mẫu được quản lý trong hồ sơ tương ứng và Lịch sử thao tác.</p>`}else if(def.type==='chapter'){content=chapters.map(ch=>{const cr=criteria.filter(c=>+c.chapter===+ch.number),rr=qdFormRecords.filter(r=>+r.data?.chapter===+ch.number),sum=arows.find(x=>+x.number===+ch.number)||{};return `<section class="report-section"><h3>Chương ${ch.number}. ${esc(ch.title)}</h3><p>${sum.assessed||0}/${ch.criteria_count} tiêu chí đã đánh giá · ${Number(sum.achieved_points||0).toFixed(1).replace('.0','')}/${Number(sum.applicable_max_points||ch.max_points).toFixed(1).replace('.0','')} điểm · ${rr.length} hồ sơ/biểu mẫu đã tạo.</p></section>`}).join('')}else{const gaps=criteria.filter(c=>['partial','fail'].includes(c.result));const overdue=qdFormRecords.filter(r=>r.due_date&&r.due_date<new Date().toISOString().slice(0,10)&&!['done','closed','approved'].includes(r.status));content=`<div class="qd2429-report-kpis"><div><b>${percent}%</b><span>tỷ lệ điểm</span></div><div><b>${gaps.length}</b><span>tiêu chí cần cải tiến</span></div><div><b>${qdFormRecords.length}</b><span>bản ghi quản lý</span></div><div><b>${overdue.length}</b><span>hồ sơ/công việc quá hạn</span></div></div><h3>Nội dung cần lãnh đạo xem xét</h3><ul>${gaps.slice(0,20).map(c=>`<li><b>${esc(c.code)}</b> ${esc(c.title)} — ${esc(resultLabel[c.result]||c.result)}${c.note?`: ${esc(c.note)}`:''}</li>`).join('')||'<li>Chưa có nội dung cần cải tiến được ghi nhận.</li>'}</ul>`}return `<article class="card panel print-report iso-form-a4" id="qd2429ReportExport">${head}${content}<div class="form-signatures"><div>Người lập báo cáo<br><small>(Ký, ghi rõ họ tên)</small></div><div>Trưởng khoa Xét nghiệm<br><small>(Ký, ghi rõ họ tên)</small></div><div>Lãnh đạo xem xét<br><small>(Ký, ghi rõ họ tên)</small></div></div></article>`};
 const openQdReport=(def)=>{openDrawer(def.title,'qd2429',`<div class="export-toolbar"><button class="btn" id="qdRptPrint">In A4</button><button class="btn" id="qdRptPdf">PDF A4</button><button class="btn primary" id="qdRptDocx">DOCX A4</button></div>${qdReportHtml(def)}`,{layout:'modal'});$('#qdRptPrint')?.addEventListener('click',()=>{auditUiEvent('print_a4',{module:'qd2429',title:def.title,format:'print'});window.print()});$('#qdRptPdf')?.addEventListener('click',()=>exportElementPdf($('#qd2429ReportExport'),`${safeFileName(def.id+'-'+def.title)}.pdf`,{action:'report_export',module:'qd2429',title:def.title,period:assessment.period}));$('#qdRptDocx')?.addEventListener('click',()=>exportElementDocx($('#qd2429ReportExport'),`${safeFileName(def.id+'-'+def.title)}.docx`,def.title,{action:'report_export',module:'qd2429',title:def.title,period:assessment.period}))};
 const dashboardFormHubHtml=()=>{const today=new Date().toISOString().slice(0,10),overdue=qdFormRecords.filter(r=>r.due_date&&r.due_date<today&&!['done','closed','approved'].includes(r.status));return `<section class="card panel qd2429-dashboard-form-hub"><div class="panel-head"><div><h3>Biểu mẫu, sổ theo dõi và báo cáo</h3><div class="panel-sub">45 mẫu chuyên biệt QĐ 2429 + 16 biểu mẫu ISO dùng chung; quản lý bản ghi, hạn xử lý, minh chứng và báo cáo A4.</div></div><button class="btn primary small" data-q2429-open-forms>Mở Biểu mẫu & Báo cáo</button></div><div class="qd2429-dashboard-grid"><div class="card qd2429-score-card"><small>Bản ghi đã tạo</small><strong>${qdFormRecords.length}</strong><span>hồ sơ QĐ 2429</span></div><div class="card qd2429-score-card"><small>Quá hạn</small><strong>${overdue.length}</strong><span>cần xử lý</span></div><div class="card qd2429-score-card"><small>Mẫu chuyên biệt</small><strong>${qdTemplates.length}</strong><span>phủ 169 tiêu chí</span></div><div class="card qd2429-score-card"><small>Báo cáo</small><strong>${reportDefs.length}</strong><span>PDF/DOCX A4</span></div></div></section>`};
 const formsHubHtml=()=>{const today=new Date().toISOString().slice(0,10),overdue=qdFormRecords.filter(r=>r.due_date&&r.due_date<today&&!['done','closed','approved'].includes(r.status));const templates=qdTemplates.map(t=>`<article class="qd2429-form-template" data-qd-template-card data-chapter="${t.chapter}" data-hay="${esc((t.id+' '+t.title+' '+(t.criteria_refs||[]).join(' ')).toLowerCase())}"><div><span class="code">${esc(t.id)}</span><span class="badge">Chương ${t.chapter}</span></div><h4>${esc(t.title)}</h4><p>${esc(t.purpose)}</p><small>Tiêu chí: ${esc((t.criteria_refs||[]).join(', '))} · ${esc(t.frequency||'')}</small><button class="btn primary small" data-q2429-new-form="${esc(t.id)}">Tạo bản ghi</button></article>`).join('');const shared=reusedIsoForms.map(t=>`<article class="qd2429-form-template shared"><div><span class="code">${esc(t.id)}</span><span class="badge active">Dùng chung ISO</span></div><h4>${esc(t.title)}</h4><p>${esc(t.purpose||'')}</p><small>QĐ 2429: ${esc((t._qd?.criteria_refs||[]).join(', '))}</small><button class="btn small" data-q2429-shared-form="${esc(t.id)}">Mở mẫu dùng chung</button></article>`).join('');const records=qdFormRecords.map(r=>`<tr data-q2429-form-record="${r.id}"><td><span class="code">${esc(r.code||'#'+r.id)}</span></td><td><strong>${esc(r.title)}</strong><small>Chương ${esc(r.data?.chapter||'—')} · ${esc((r.data?.criteria_refs||[]).join(', '))}</small></td><td>${esc(r.owner_name||r.owner_ref||'—')}</td><td>${fmtDate(r.due_date)}</td><td><span class="badge ${esc(r.status)}">${esc(statusLabels[r.status]||r.status)}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Chưa tạo bản ghi QĐ 2429 từ các biểu mẫu.</td></tr>';const reports=reportDefs.map(r=>`<button class="report-period-card" data-q2429-report="${esc(r.id)}"><strong>${esc(r.title)}</strong><p>${esc(r.description||'')}</p><span>Tạo báo cáo A4 ›</span></button>`).join('');return `<section class="qd2429-dashboard-grid qd2429-form-kpis"><div class="card qd2429-score-card"><small>Mẫu chuyên biệt 2429</small><strong>${qdTemplates.length}</strong><span>phủ 12 chương</span></div><div class="card qd2429-score-card"><small>Mẫu ISO tái sử dụng</small><strong>${reusedIsoForms.length}</strong><span>không tạo bản sao</span></div><div class="card qd2429-score-card"><small>Bản ghi đã tạo</small><strong>${qdFormRecords.length}</strong><span>có thể gắn minh chứng</span></div><div class="card qd2429-score-card"><small>Quá hạn</small><strong>${overdue.length}</strong><span>cần theo dõi</span></div></section><section class="card panel"><div class="panel-head"><div><h3>Biểu mẫu chuyên biệt QĐ 2429</h3><div class="panel-sub">Tạo bản ghi trực tiếp, giao người phụ trách, đặt hạn, lưu ghi chú và đính kèm minh chứng. Một mẫu có thể phục vụ nhiều tiêu chí.</div></div></div><div class="qd2429-form-filter"><input id="qd2429FormSearch" placeholder="Tìm biểu mẫu hoặc mã tiêu chí…"><select id="qd2429FormChapter"><option value="all">Tất cả 12 chương</option>${chapters.map(ch=>`<option value="${ch.number}">Chương ${ch.number}</option>`).join('')}</select></div><div class="qd2429-form-template-grid">${templates}</div></section><section class="card panel"><div class="panel-head"><div><h3>Biểu mẫu ISO dùng chung</h3><div class="panel-sub">Các biểu mẫu này đã tồn tại trong hệ thống và được ánh xạ sang QĐ 2429; không tạo thêm bản sao.</div></div><button class="btn small" data-go-global-forms>Mở thư viện Biểu mẫu & hồ sơ</button></div><div class="qd2429-form-template-grid">${shared}</div></section><section class="card panel"><div class="panel-head"><div><h3>Sổ đăng ký bản ghi QĐ 2429</h3><div class="panel-sub">Theo dõi bản ghi được tạo từ các biểu mẫu chuyên biệt.</div></div><span class="badge active">${qdFormRecords.length} bản ghi</span></div><div class="table-card"><table class="data-table"><thead><tr><th>MÃ</th><th>BIỂU MẪU / HỒ SƠ</th><th>PHỤ TRÁCH</th><th>HẠN</th><th>TRẠNG THÁI</th></tr></thead><tbody>${records}</tbody></table></div></section><section class="card panel"><div class="panel-head"><div><h3>Báo cáo QĐ 2429</h3><div class="panel-sub">Tạo báo cáo từ dữ liệu tự đánh giá và sổ bản ghi; có thể in hoặc xuất PDF/DOCX A4.</div></div></div><div class="report-period-grid">${reports}</div></section>`};
 const wireFormsHub=()=>{$$('[data-q2429-new-form]',body).forEach(b=>b.onclick=()=>openQdFormRecord(qdTemplateById[b.dataset.q2429NewForm]));$$('[data-q2429-shared-form]',body).forEach(b=>{const t=sharedIsoForms.find(x=>x.id===b.dataset.q2429SharedForm);b.onclick=()=>t&&openFormTemplate(t)});$$('[data-q2429-form-record]',body).forEach(row=>row.onclick=()=>{const r=qdFormRecords.find(x=>+x.id===+row.dataset.q2429FormRecord);const t=qdTemplateById[r?.data?.template_id];if(r&&t)openQdFormRecord(t,r)});$$('[data-q2429-report]',body).forEach(b=>{const def=reportDefs.find(x=>x.id===b.dataset.q2429Report);b.onclick=()=>def&&openQdReport(def)});body.querySelector('[data-go-global-forms]')?.addEventListener('click',()=>go('forms'));const filter=()=>{const q=(body.querySelector('#qd2429FormSearch')?.value||'').trim().toLowerCase(),ch=body.querySelector('#qd2429FormChapter')?.value||'all';$$('[data-qd-template-card]',body).forEach(card=>{card.hidden=!!((q&&!card.dataset.hay.includes(q))||(ch!=='all'&&card.dataset.chapter!==ch))})};body.querySelector('#qd2429FormSearch')?.addEventListener('input',filter);body.querySelector('#qd2429FormChapter')?.addEventListener('change',filter)};
 const chapterRows=chapters.map(ch=>`<article class="qd2429-chapter"><div class="qd2429-chapter-num">${ch.number}</div><div class="qd2429-chapter-main"><div class="qd2429-chapter-kicker">Chương ${ch.number}</div><h3>${esc(ch.title)}</h3><p>${esc(ch.focus||'')}</p><div class="qd2429-meta"><span>${ch.criteria_count} tiêu chí</span><span>${ch.max_points} điểm</span>${(ch.mandatory_one_star||[]).length?`<span>${(ch.mandatory_one_star||[]).length} tiêu chí *</span>`:''}${(ch.mandatory_three_star||[]).length?`<span>${(ch.mandatory_three_star||[]).length} tiêu chí ***</span>`:''}</div></div></article>`).join('');
 const mapping=chapters.map(ch=>`<tr><td><strong>Chương ${ch.number}</strong></td><td>${esc(ch.title)}</td><td>${(ch.iso_links||[]).map(x=>`<span class="clause-chip">${esc(x)}</span>`).join(' ')||'—'}</td><td><span class="badge review">${esc(ch.mapping_status||'GIAO THOA MỘT PHẦN')}</span></td></tr>`).join('');
 const dashboardHtml=()=>`<section class="qd2429-dashboard-grid"><div class="card qd2429-score-card"><small>Kỳ tự đánh giá</small><strong>${esc(assessment.period||'—')}</strong><span>${assessment.status==='published'?'Đã công bố':'Bản nháp'}</span></div><div class="card qd2429-score-card"><small>Điểm hiện tại</small><strong>${Number(totals.achieved_points||0).toFixed(1).replace('.0','')} / ${Number(totals.applicable_max_points||268).toFixed(1).replace('.0','')}</strong><span>${percent}% trên điểm áp dụng · chuẩn 268</span></div><div class="card qd2429-score-card"><small>Mức chất lượng</small><strong>${esc(level)}</strong><span>${oneOk?'Đủ nhóm *':'Còn thiếu nhóm *'} · ${threeOk?'Đủ nhóm ***':'Còn thiếu nhóm ***'}</span></div><div class="card qd2429-score-card"><small>Tiêu chí đã đánh giá</small><strong>${totals.assessed||0} / ${totals.criteria||169}</strong><span>${totals.not_applicable||0} tiêu chí không áp dụng</span></div></section><section class="card panel qd2429-chapter-dashboard"><div class="panel-head"><div><h3>Tiến độ theo 12 chương</h3><div class="panel-sub">Theo dõi mức hoàn thành, điểm đạt được và điều kiện tiêu chí bắt buộc theo từng chương.</div></div><button class="btn primary small" data-q2429-open-assessment>Mở Tự đánh giá</button></div><div class="qd2429-progress-list">${arows.map(x=>{const pc=x.criteria_count?Math.round((+x.assessed||0)*100/x.criteria_count):0,sp=Number(x.percent||0);return `<div class="qd2429-progress-row"><div><strong>Chương ${x.number}. ${esc(x.title)}</strong><small>${x.assessed}/${x.criteria_count} tiêu chí · ${Number(x.achieved_points||0).toFixed(1).replace('.0','')}/${Number(x.applicable_max_points||x.max_points||0).toFixed(1).replace('.0','')} điểm áp dụng</small></div><div class="qd2429-bars"><div><span style="width:${pc}%"></span></div><small>${pc}% hoàn thành · ${sp}% điểm</small></div></div>`}).join('')}</div></section><section class="card panel"><div class="panel-head"><div><h3>Cách tính và xếp mức</h3><div class="panel-sub">Mỗi tiêu chí được chấm Đạt, Đạt một phần, Không đạt hoặc Không áp dụng. Đạt một phần chỉ xuất hiện ở tiêu chí có cấu trúc cho phép.</div></div></div><div class="qd2429-rule-grid">${(levels||[]).map(x=>`<div><strong>${esc(x.label)}</strong><span>${x.key==='unclassified'?'Dưới 20% hoặc thiếu tiêu chí bắt buộc':`${x.min_percent}% – ${x.max_percent>=100?'100':`<${x.max_percent}`}%`}</span><small>${esc(x.requires||'')}</small></div>`).join('')}</div></section>`;
 const handbookHtml=()=>{const og=d.operational_guidance||{};return `<section class="card panel qd2429-operational-guide"><div class="panel-head"><div><h3>Chu trình quản lý QĐ 2429</h3><div class="panel-sub">Sử dụng Sổ tay không chỉ để đọc tiêu chí mà để lập kế hoạch, theo dõi, tự đánh giá, cải tiến và báo cáo theo một chu trình thống nhất.</div></div></div><div class="qd2429-cycle-grid">${(og.steps||[]).map((v,i)=>`<div><span>${i+1}</span><p>${esc(v)}</p></div>`).join('')}</div><div class="context-columns qd2429-ops-summary"><section><h4>Nhịp theo dõi gợi ý</h4>${listHtml(og.cadence||[])}</section><section><h4>Báo cáo cốt lõi</h4>${listHtml(og.core_reports||[])}</section></div></section><div class="handbook-grid handbook-grid-compact qd2429-reader-grid">${handbook.map((x,i)=>`<button class="handbook-card handbook-card-compact qd2429-reader-card" data-q2429-handbook="${i}"><div class="clause-row"><span class="clause-chip">Chương ${x.chapter}</span></div><strong>${esc(x.title)}</strong><p>${esc(x.summary||'')}</p><span>Mở Sổ tay →</span></button>`).join('')}</div>`};
 const resultLabel={unassessed:'Chưa đánh giá',pass:'Đạt',partial:'Đạt một phần',fail:'Không đạt',na:'Không áp dụng'};
 const scoreFor=(c,result)=>result==='pass'?Number(c.max_points||0):(result==='partial'&&c.partial_allowed?Number(c.max_points||0)/2:(result==='fail'||result==='na'?0:null));
 const criterionCard=c=>{const marker=c.mandatory_marker||'',markerHtml=marker?`<span class="qd2429-star qd2429-star-${marker==='***'?'3':'1'}">${marker==='***'?'*** Bắt buộc mức 3':'* Bắt buộc'}</span>`:'';const score=c.score===null||c.score===undefined?'—':Number(c.score).toFixed(1).replace('.0',''),linked=formsForCriterion(c.code);return `<article class="qd2429-criterion-card ${marker?'mandatory':''}" data-qcriterion="${esc(c.code)}"><div class="qd2429-criterion-head"><div><div class="qd2429-criterion-code">${esc(c.code)} ${markerHtml}</div><h4>${esc(c.title)}</h4></div><span class="qd2429-max-score">Tối đa ${Number(c.max_points||0).toFixed(1).replace('.0','')} điểm</span></div><div class="form-grid qd2429-criterion-form"><div class="field"><label>Kết quả đánh giá</label><select data-qcrit="result"><option value="unassessed" ${c.result==='unassessed'?'selected':''}>Chưa đánh giá</option><option value="pass" ${c.result==='pass'?'selected':''}>Đạt</option>${c.partial_allowed?`<option value="partial" ${c.result==='partial'?'selected':''}>Đạt một phần</option>`:''}<option value="fail" ${c.result==='fail'?'selected':''}>Không đạt</option><option value="na" ${c.result==='na'?'selected':''}>Không áp dụng</option></select></div><div class="field"><label>Điểm</label><input data-qcrit-score value="${score}" readonly aria-label="Điểm tự động theo kết quả đánh giá"></div><div class="field full"><label>Ghi chú / lý do / nội dung cần cải tiến</label><textarea data-qcrit="note" placeholder="Bắt buộc nêu lý do khi Đạt một phần, Không đạt hoặc Không áp dụng.">${esc(c.note||'')}</textarea></div><div class="field full"><label>Liên kết minh chứng (nếu có)</label><input data-qcrit="evidence_url" type="url" value="${esc(c.evidence_url||'')}" placeholder="https://..."></div></div>${linked.total?`<div class="qd2429-criterion-tools"><button type="button" class="btn small" data-qcrit-forms="${esc(c.code)}">Biểu mẫu liên quan · ${linked.total}</button></div>`:''}</article>`};
 const assessmentHtml=()=>{const byChapter=new Map(chapters.map(ch=>[+ch.number,[]]));criteria.forEach(c=>{if(!byChapter.has(+c.chapter))byChapter.set(+c.chapter,[]);byChapter.get(+c.chapter).push(c)});return `<section class="card panel qd2429-assessment-shell"><div class="panel-head"><div><h3>Tự đánh giá QĐ 2429 — 169 tiêu chí</h3><div class="panel-sub">Chấm trực tiếp từng tiêu chí. Điểm được tính tự động theo lựa chọn đánh giá; tiêu chí có dấu * hoặc *** được hiển thị nổi bật.</div></div></div><form id="qd2429AssessmentForm"><div class="qd2429-assessment-toolbar"><div class="field"><label>Kỳ đánh giá</label><input name="period" value="${esc(assessment.period||new Date().getFullYear())}"></div><div class="field"><label>Trạng thái</label><select name="status"><option value="draft" ${assessment.status!=='published'?'selected':''}>Bản nháp</option><option value="published" ${assessment.status==='published'?'selected':''}>Công bố</option></select></div><div class="field"><label>Lọc tiêu chí</label><select id="qd2429CriterionFilter"><option value="all">Tất cả</option><option value="unassessed">Chưa đánh giá</option><option value="mandatory">Tiêu chí * / ***</option><option value="needs_action">Không đạt / Đạt một phần</option></select></div><div class="qd2429-live-summary"><strong>${totals.assessed||0}/${totals.criteria||169}</strong><span>đã đánh giá</span></div></div><div class="qd2429-criterion-chapters">${chapters.map((ch,idx)=>{const rows=byChapter.get(+ch.number)||[],sum=arows.find(x=>+x.number===+ch.number)||{};return `<details class="qd2429-criterion-chapter" data-qchapter="${ch.number}" ${idx===0?'open':''}><summary><span><b>Chương ${ch.number}</b> ${esc(ch.title)}</span><small>${sum.assessed||0}/${ch.criteria_count} tiêu chí · ${Number(sum.achieved_points||0).toFixed(1).replace('.0','')}/${Number(sum.applicable_max_points||ch.max_points).toFixed(1).replace('.0','')} điểm</small></summary><div class="qd2429-criterion-list">${rows.map(criterionCard).join('')}</div></details>`}).join('')}</div>${assessment.canManage?`<div class="form-actions qd2429-sticky-save"><button class="btn primary" type="submit">Lưu Tự đánh giá</button></div>`:'<div class="note">Tài khoản hiện tại chỉ có quyền xem kết quả tự đánh giá.</div>'}</form></section>`};
 $('#content').innerHTML=`<section class="qd2429-hero"><div><span class="eyebrow">BỘ Y TẾ · QUYẾT ĐỊNH 2429/QĐ-BYT</span><h2>Quản lý chất lượng xét nghiệm theo QĐ 2429</h2><p>Tổng quan, tự đánh giá theo 169 tiêu chí, Sổ tay hướng dẫn và đối chiếu các nhóm nội dung liên quan trong cùng một phân hệ.</p></div><div class="qd2429-kpis"><div><strong>${d.totals?.chapters||12}</strong><span>Chương</span></div><div><strong>${d.totals?.criteria||169}</strong><span>Tiêu chí</span></div><div><strong>${d.totals?.max_points||268}</strong><span>Điểm tối đa</span></div></div></section><div class="tabs qd2429-tabs"><button class="tab active" data-q2429-tab="dashboard">Tổng quan</button><button class="tab" data-q2429-tab="criteria">Bộ tiêu chí</button><button class="tab" data-q2429-tab="assessment">Tự đánh giá</button><button class="tab" data-q2429-tab="handbook">Sổ tay 2429</button><button class="tab" data-q2429-tab="mapping">Ánh xạ ISO ↔ 2429</button><button class="tab" data-q2429-tab="forms">Biểu mẫu & Báo cáo</button></div><section id="qd2429Body"></section>`;
 const body=$('#qd2429Body');
 const openHandbook=(x)=>{const lesson=(d.lessons||[]).find(l=>+l.chapter===+x.chapter)||{};const learning=uniqueTextItems([...(x.learning_points||[]),...(lesson.key_points||[]).filter(v=>!/(ISO|record ISO|không suy diễn)/i.test(String(v)))]);const quiz=(x.quiz||[]).length?x.quiz:(lesson.quiz||[]).filter(q=>!/(ISO|record ISO)/i.test(String(q.q||'')+' '+String(q.a||'')));const sources=d.guidance_sources||[];const indicators=(x.suggested_indicators||[]).map(k=>`<div class="qd2429-indicator-card"><strong>${esc(k.name||'')}</strong><p>${esc(k.method||'')}</p><span>${esc(k.frequency||'')}</span></div>`).join('');openDrawer(x.title,'qd2429',`<div class="knowledge-detail applied-learning qd2429-reader"><p class="lead content-core">${esc(x.summary)}</p>${learning.length?`<section><h4>Điểm cần nắm</h4>${listHtml(learning)}</section>`:''}<section class="practice-box"><h4>Cách thực hiện trong thực tế</h4><ol>${(x.how_to||[]).map(v=>`<li>${esc(v)}</li>`).join('')}</ol></section>${(x.monitoring_and_supervision||[]).length?`<section class="qd2429-monitor-box"><h4>Theo dõi và giám sát</h4>${listHtml(x.monitoring_and_supervision)}</section>`:''}${indicators?`<section><h4>Chỉ số giám sát gợi ý</h4><div class="qd2429-indicator-grid">${indicators}</div></section>`:''}${(x.planning_and_improvement||[]).length?`<section class="qd2429-improvement-box"><h4>Lập kế hoạch và cải tiến</h4>${listHtml(x.planning_and_improvement)}</section>`:''}${(x.reporting||[]).length?`<section class="qd2429-report-box"><h4>Báo cáo và xem xét</h4>${listHtml(x.reporting)}</section>`:''}${(x.forms_and_records||[]).length?`<section class="qd2429-form-box"><h4>Biểu mẫu và hồ sơ hỗ trợ</h4>${listHtml(x.forms_and_records)}<button class="btn small" data-q2429-common-forms>Mở Biểu mẫu & Báo cáo</button></section>`:''}${(x.evidence_examples||[]).length?`<section class="evidence-box"><h4>Hồ sơ / bằng chứng thường cần</h4>${listHtml(x.evidence_examples)}</section>`:''}<section class="attention-box"><h4>${semanticSvg('warning')}<span>Điểm cần tránh</span></h4><p>${esc(x.caution||'')}</p></section>${x.management_note?`<section class="reference-note"><h4>Nguyên tắc áp dụng</h4><p>${esc(x.management_note)}</p></section>`:''}${quiz.length?`<section><h4>Câu hỏi tự kiểm tra</h4>${quiz.map(q=>`<div class="quiz-question"><strong>${esc(q.q)}</strong><p>${esc(q.a)}</p></div>`).join('')}</section>`:''}${(x.iso_links||[]).length?`<section class="reference-note"><h4>Nội dung ISO 15189 liên quan</h4><div class="clause-row">${(x.iso_links||[]).map(v=>`<span class="clause-chip">${esc(v)}</span>`).join('')}</div></section>`:''}<section><h4>Nguồn hướng dẫn</h4><div class="iso-reference-list">${sources.map(src=>`<a class="iso-reference-card" href="${esc(src.url)}" target="_blank" rel="noopener"><span>${esc(src.role||'Nguồn tham khảo')}</span><strong>${esc(src.title)}</strong><small>${esc(src.organization||'')}</small></a>`).join('')}</div></section></div>`,{layout:'modal'});setTimeout(()=>document.querySelector('[data-q2429-common-forms]')?.addEventListener('click',()=>{closeDrawer();show('forms')}),0)};
 const wireHandbook=()=>$$('[data-q2429-handbook]',body).forEach(b=>b.onclick=()=>openHandbook(handbook[+b.dataset.q2429Handbook]));
 const wireAssessment=()=>{const form=$('#qd2429AssessmentForm');if(!form)return;$$('[data-qcriterion]',form).forEach(card=>{const select=$('[data-qcrit="result"]',card),score=$('[data-qcrit-score]',card),c=criteria.find(x=>x.code===card.dataset.qcriterion);select?.addEventListener('change',()=>{const v=scoreFor(c,select.value);if(score)score.value=v===null?'—':Number(v).toFixed(1).replace('.0','')})});$$('[data-qcrit-forms]',form).forEach(btn=>btn.addEventListener('click',()=>{show('forms');setTimeout(()=>{const search=body.querySelector('#qd2429FormSearch');if(search){search.value=btn.dataset.qcritForms;search.dispatchEvent(new Event('input'))}},0)}));$('#qd2429CriterionFilter')?.addEventListener('change',e=>{const mode=e.target.value;$$('[data-qcriterion]',form).forEach(card=>{const c=criteria.find(x=>x.code===card.dataset.qcriterion),result=$('[data-qcrit="result"]',card)?.value||'unassessed';const visible=mode==='all'||(mode==='unassessed'&&result==='unassessed')||(mode==='mandatory'&&!!c?.mandatory_marker)||(mode==='needs_action'&&['partial','fail'].includes(result));card.hidden=!visible});$$('.qd2429-criterion-chapter',form).forEach(ch=>{const any=$$('[data-qcriterion]',ch).some(x=>!x.hidden);ch.hidden=!any;if(any)ch.open=true})});form.addEventListener('submit',async e=>{e.preventDefault();const p={period:form.period.value,status:form.status.value,criteria:{}};$$('[data-qcriterion]',form).forEach(card=>{const obj={};$$('[data-qcrit]',card).forEach(el=>obj[el.dataset.qcrit]=el.value);p.criteria[card.dataset.qcriterion]=obj});try{await api('knowledge/qd2429/assessment',{method:'POST',json:p});toast('Đã lưu tự đánh giá QĐ 2429');renderQD2429()}catch(err){toast(err.message,'err')}})};
 const show=(tab)=>{state.qdTab=tab;$$('.qd2429-tabs .tab').forEach(b=>b.classList.toggle('active',b.dataset.q2429Tab===tab));if(tab==='dashboard'){body.innerHTML=dashboardHtml()+dashboardFormHubHtml();body.querySelector('[data-q2429-open-assessment]')?.addEventListener('click',()=>show('assessment'));body.querySelector('[data-q2429-open-forms]')?.addEventListener('click',()=>show('forms'));return}if(tab==='criteria'){body.innerHTML=`<div class="qd2429-grid">${chapterRows}</div>`;return}if(tab==='assessment'){body.innerHTML=assessmentHtml();wireAssessment();return}if(tab==='handbook'){body.innerHTML=handbookHtml();wireHandbook();return}if(tab==='mapping'){body.innerHTML=`<div class="qd2429-map-note"><strong>Đối chiếu nội dung liên quan</strong><span>Ma trận giúp nhận diện chủ đề có giao thoa để thuận tiện tra cứu và sử dụng bằng chứng phù hợp.</span></div><div class="table-card"><table class="data-table"><thead><tr><th>QĐ 2429</th><th>Nội dung</th><th>ISO liên quan</th><th>Mức ánh xạ</th></tr></thead><tbody>${mapping}</tbody></table></div>`;return}body.innerHTML=formsHubHtml();wireFormsHub()};
 $$('.qd2429-tabs .tab').forEach(b=>b.onclick=()=>show(b.dataset.q2429Tab));
 show(state.qdTab||'dashboard');
}

function clarityText(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase()}
function handbookTopic(ch){const clauses=(ch.clauses||[]).map(String);return {overview:clauses.some(c=>/^1$|giới thiệu/i.test(c)),governance:clauses.some(c=>/^[45](\.|$)/.test(c)),resources:clauses.some(c=>/^6(\.|$)/.test(c)),process:clauses.some(c=>/^7(\.|$)/.test(c)),system:clauses.some(c=>/^8(\.|$)/.test(c))}}
function clarityHandbookCard(ch,i){const clauses=ch.clauses||[],shown=clauses.slice(0,3);return `<button type="button" class="mc-handbook-card" data-handbook="${i}"><span class="mc-card-top"><span class="mc-index">${String(i+1).padStart(2,'0')}</span><span class="mc-clause-list">${shown.map(c=>`<span>${esc(c)}</span>`).join('')}${clauses.length>3?`<span title="${esc(clauses.join(', '))}">+${clauses.length-3}</span>`:''}</span></span><strong>${esc(ch.title)}</strong><span class="mc-card-description">${esc(ch.summary||'')}</span><span class="mc-card-link">Đọc hướng dẫn <span aria-hidden="true">→</span></span></button>`}
async function renderHandbook(){
 const data=await api('knowledge/handbook');if(state.module!=='handbook')return;
 const chapters=data.chapters||[],topics=[['all','Tất cả'],['overview','Tổng quan'],['governance','Quản trị'],['resources','Nguồn lực'],['process','Quá trình xét nghiệm'],['system','Hệ thống quản lý']];
 $('#content').innerHTML=`<div class="module-clarity mc-handbook"><section class="mc-intro"><div><span class="mc-eyebrow">TRA CỨU & ÁP DỤNG</span><h2>Sổ tay TCVN ISO 15189:2025</h2><p>Chọn chuyên đề để đọc hướng dẫn, cách thực hiện và hồ sơ liên quan.</p></div><div class="mc-intro-actions"><button class="btn small" data-go="compliance">Bản đồ đáp ứng</button><button class="btn small" data-go="iso">Yêu cầu ISO</button></div></section><section class="mc-panel mc-filter-panel" aria-label="Tìm chuyên đề"><div class="mc-search"><label for="handbookLocalSearch">Tìm trong sổ tay</label><input id="handbookLocalSearch" type="search" placeholder="Nhập chủ đề hoặc điều khoản, ví dụ: 6.2, nhân sự…"></div><div class="mc-filter-tabs" role="group" aria-label="Nhóm chuyên đề">${topics.map(([key,label])=>`<button type="button" data-handbook-topic="${key}" aria-pressed="${key==='all'}">${label}</button>`).join('')}</div><p id="handbookResultCount" class="mc-result-count" aria-live="polite"></p></section><div id="handbookChapterGrid" class="mc-handbook-grid"></div></div>`;
 let topic='all';const draw=()=>{const query=clarityText($('#handbookLocalSearch').value.trim());const rows=chapters.map((ch,i)=>({ch,i})).filter(({ch})=>(topic==='all'||handbookTopic(ch)[topic])&&clarityText([ch.title,ch.summary,...(ch.clauses||[])].join(' ')).includes(query));$('#handbookResultCount').textContent=`${rows.length}/${chapters.length} chuyên đề`;$('#handbookChapterGrid').innerHTML=rows.map(({ch,i})=>clarityHandbookCard(ch,i)).join('')||'<div class="mc-empty">Không có chuyên đề phù hợp. Hãy đổi từ khóa hoặc chọn Tất cả.</div>';$$('[data-handbook]').forEach(b=>b.onclick=()=>{const ch=chapters[+b.dataset.handbook];openDrawer(ch.title,'handbook',handbookChapterHtml(ch),{layout:'modal'})})};
 $('#handbookLocalSearch').addEventListener('input',draw);$$('[data-handbook-topic]').forEach(b=>b.onclick=()=>{topic=b.dataset.handbookTopic;$$('[data-handbook-topic]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw()});$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));draw();
}
function implementationStateLabel(x){return x.status_label||({not_started:'Chưa bắt đầu',in_progress:'Đang thực hiện',review:'Chờ rà soát',done:'Hoàn thành',completed:'Hoàn thành',closed:'Đã đóng',blocked:'Đang vướng'}[x.status]||x.status||'Chưa bắt đầu')}
function implementationPastDue(x,today=new Date()){const due=x.due_date||'';return !!due&&new Date(due+'T23:59:59')<today&&!['done','completed','closed'].includes(x.status)}
function clarityImplementationItem(x){const past=implementationPastDue(x);const fields=[['Trực tiếp thực hiện',x.responsible],['Chịu trách nhiệm cuối cùng',x.accountable],['Phối hợp / được thông tin',x.consulted_informed],['Công việc phụ thuộc',x.dependencies],['Minh chứng cần có',x.evidence],['Tiêu chí hoàn thành',x.acceptance_criteria],['Cơ sở thời hạn',x.time_basis],['Ghi chú',x.note]];return `<details class="mc-work-item${past?' mc-past-due':''}"><summary><span class="mc-work-number">${esc(x.seq)}</span><span class="mc-work-copy"><span class="mc-work-meta"><span class="mc-priority">${esc(x.priority||'—')}</span><span>${esc(x.phase||'')}</span></span><strong>${esc(x.task||'')}</strong><span class="mc-work-owner">${esc(x.responsible||'Chưa xác định đầu mối')} · ISO ${esc(x.clauses||'—')}</span></span><span class="mc-work-state"><span class="mc-status mc-status-${esc(x.status||'not_started')}">${esc(implementationStateLabel(x))}</span><time datetime="${esc(x.due_date||'')}">${fmtDate(x.due_date)}</time>${past?'<span class="mc-due-label">Quá mốc đề xuất</span>':''}</span><span class="mc-expand" aria-hidden="true">⌄</span></summary><div class="mc-work-detail"><dl>${fields.filter(([,value])=>value).map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></div></details>`}


const complianceStateLabels={pending:'Chưa thực hiện',in_progress:'Đang thực hiện',ready:'Đã sẵn sàng',verified:'Đã xác minh',not_applicable:'Không áp dụng'};
const complianceStageLabels={understand:'Hiểu yêu cầu',procedure:'Quy trình / tài liệu',assignment:'Phân công trách nhiệm',evidence:'Bằng chứng',effectiveness:'Đánh giá hiệu lực'};
function complianceStateClass(s){return ['ready','verified','not_applicable'].includes(s)?'done':s==='in_progress'?'progress':'pending'}
function complianceEditorHtml(item){const st=item.states||{};const stateSelect=(k,v)=>`<div class="field"><label>${esc(complianceStageLabels[k]||k)}</label><select name="${k}">${Object.entries(complianceStateLabels).map(([x,l])=>`<option value="${x}" ${v===x?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;return `<form id="complianceForm"><div class="compliance-editor-head"><span class="clause-chip">${esc(item.clause)}</span><h3>${esc(item.title)}</h3><strong>${item.readiness}%</strong></div><div class="form-grid">${stateSelect('understand',st.understand)}${stateSelect('procedure',st.procedure)}${stateSelect('assignment',st.assignment)}${stateSelect('evidence',st.evidence)}${stateSelect('effectiveness',st.effectiveness)}<div class="field"><label>Đầu mối</label><select name="owner_ref">${ownerOptions(item.owner_ref||'')}</select></div><div class="field"><label>Hạn hoàn thành</label><input type="date" name="due_date" value="${esc(item.due_date||'')}"></div><div class="field full"><label>Ghi chú triển khai</label><textarea name="note">${esc(item.note||'')}</textarea></div></div><div class="compliance-related"><strong>Dữ liệu liên quan</strong><span>Quy trình ${item.related_counts?.documents||0}</span><span>Biểu mẫu ${item.related_counts?.forms||0}</span><span>Nhiệm vụ ${item.related_counts?.tasks||0}</span><span>Rủi ro ${item.related_counts?.risks||0}</span><span>Không phù hợp/Khắc phục ${(item.related_counts?.nc||0)+(item.related_counts?.capa||0)}</span></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu & xác nhận rà soát</button></div></form>`}
async function openComplianceItem(item){if(!canManage('iso')){const st=item.states||{};const rows=[['Hiểu',st.understand],['Quy trình',st.procedure],['Phân công',st.assignment],['Bằng chứng',st.evidence],['Hiệu lực',st.effectiveness]].map(([l,v])=>`<div class="mapping-row"><strong>${l}</strong><span class="effectiveness ${complianceStateClass(v)}">${esc(complianceStateLabels[v]||v||'Chưa cập nhật')}</span></div>`).join('');openDrawer(`${item.clause} · ${item.title}`,'compliance',`<div class="compliance-editor-head"><span class="clause-chip">${esc(item.clause)}</span><h3>${esc(item.title)}</h3><strong>${item.readiness}%</strong></div><div class="mapping-list">${rows}</div><div class="note">Đầu mối: ${esc(item.owner_ref||'Chưa phân công')}${item.due_date?' · Hạn '+fmtDate(item.due_date):''}</div>${item.note?`<div class="note">${esc(item.note)}</div>`:''}`,{layout:'modal'});return}openDrawer(`${item.clause} · ${item.title}`,'compliance',complianceEditorHtml(item),{layout:'modal'});$$('[data-close]',$('#drawerBody')).forEach(b=>b.onclick=closeDrawer);$('#complianceForm')?.addEventListener('submit',async e=>{e.preventDefault();const j=Object.fromEntries(new FormData(e.currentTarget).entries());j.reviewed=true;try{await api(`quality-core/compliance/${encodeURIComponent(item.clause)}`,{method:'PATCH',json:j});toast('Đã cập nhật Bản đồ đáp ứng');closeDrawer();await renderComplianceMap()}catch(err){toast(err.message,'err')}})}
async function renderComplianceMap(){const data=await api('quality-core/compliance');const groups=['4','5','6','7','8'];const stageKeys=[['understand','HIỂU'],['procedure','QUY TRÌNH'],['assignment','PHÂN CÔNG'],['evidence','BẰNG CHỨNG'],['effectiveness','HIỆU LỰC']];const sections=groups.map(g=>{const rows=(data.items||[]).filter(x=>x.clause===g||x.clause.startsWith(g+'.')).map(x=>`<button class="compliance-row" data-compliance="${esc(x.clause)}"><span class="compliance-code">${esc(x.clause)}</span><span class="compliance-title"><strong>${esc(x.title)}</strong><small>${x.owner_ref?esc(x.owner_ref):'Chưa phân công'}${x.due_date?' · Hạn '+fmtDate(x.due_date):''}</small></span><span class="compliance-stages">${stageKeys.map(([k,l])=>`<i class="${complianceStateClass(x.states?.[k])}" title="${esc(l+': '+(complianceStateLabels[x.states?.[k]]||''))}"></i>`).join('')}</span><span class="compliance-pct"><b>${x.readiness}%</b><small>${x.has_evidence?'Có hồ sơ':'Chưa có hồ sơ'}</small></span><em>›</em></button>`).join('');const names={4:'4 · Yêu cầu chung',5:'5 · Cơ cấu và điều hành',6:'6 · Nguồn lực',7:'7 · Quá trình',8:'8 · Hệ thống quản lý'};return `<section class="compliance-group card"><div class="compliance-group-head"><h3>${names[g]}</h3><span>${(data.items||[]).filter(x=>x.clause.startsWith(g+'.')).length} yêu cầu</span></div>${rows}</section>`}).join('');$('#content').innerHTML=`<section class="card qms-hero"><div><span class="eyebrow">TCVN ISO 15189:2025</span><h2>Bản đồ đáp ứng ISO 15189</h2><p>Theo dõi từng yêu cầu theo 5 bước: <b>Hiểu → Quy trình → Phân công → Bằng chứng → Hiệu lực</b>.</p></div><div class="qms-hero-score"><strong>${data.ready||0}/${data.total||0}</strong><span>yêu cầu sẵn sàng đầy đủ</span></div></section><div class="compliance-legend">${stageKeys.map(([k,l])=>`<span><i></i>${l}</span>`).join('')}<button class="btn small" data-go="handbook">Mở Sổ tay ISO</button></div>${sections}`;const by=Object.fromEntries((data.items||[]).map(x=>[x.clause,x]));$$('[data-compliance]').forEach(b=>b.onclick=()=>openComplianceItem(by[b.dataset.compliance]));$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go))}
function riskScore(r,residual=false){const d=r.data||{};const a=+(residual?d.residual_likelihood:d.likelihood)||0,b=+(residual?d.residual_impact:d.impact)||0;return +(residual?d.residual_score:d.score)||a*b}
function qmsSummaryCards(module,q){if(module==='risks')return [['Rủi ro đang mở',q.risk?.open||0],['Mức cao / nghiêm trọng',q.risk?.high_critical||0],['Điều khoản chính','5.6 · 8.5']];if(module==='audits')return [['Cuộc đánh giá đang mở',q.audit?.open||0],['Phát hiện chưa đóng',q.audit?.open_findings||0],['Điều khoản','8.8.3']];if(module==='nc')return [['Phát hiện chưa đóng',q.audit?.open_findings||0],['Hành động đang mở',q.capa?.open||0],['Trình tự','Phát hiện → Nguyên nhân → Khắc phục']];if(module==='capa')return [['Hành động đang mở',q.capa?.open||0],['Quá hạn',q.capa?.overdue||0],['Chờ hiệu lực',q.capa?.awaiting_effectiveness||0],['Chưa đạt hiệu lực',q.capa?.ineffective||0]];if(module==='meetings')return [['Đầu vào sẵn sàng',(q.management_review?.readiness_pct||0)+'%'],['Nhóm đầu vào',(q.management_review?.total||10)],['Điều khoản','8.9.2–8.9.3']];return[]}
async function renderQualityModule(module){let qs=`records?module=${encodeURIComponent(module)}`;if(state.query)qs+=`&q=${encodeURIComponent(state.query)}`;if(state.status)qs+=`&status=${encodeURIComponent(state.status)}`;const jobs=[api(qs),api('quality-core/summary')];if(module==='meetings')jobs.push(api('quality-core/management-review'));const [rows,q,mr]=await Promise.all(jobs);const kpis=qmsSummaryCards(module,q).map(x=>`<div class="qms-kpi"><small>${esc(x[0])}</small><strong>${esc(x[1])}</strong></div>`).join('');let head='',body='';if(module==='risks'){head='<th>MÃ</th><th>RỦI RO</th><th>LĨNH VỰC</th><th>ĐIỂM BAN ĐẦU</th><th>RỦI RO CÒN LẠI</th><th>XEM XÉT</th><th>TRẠNG THÁI</th>';body=rows.map(r=>`<tr data-record="${r.id}"><td><span class="code">${esc(r.code||'#'+r.id)}</span></td><td><strong>${esc(r.title)}</strong><div class="meta">${esc(r.data?.clause||'')}</div></td><td>${esc(r.data?.risk_domain||'—')}</td><td><b class="risk-score">${riskScore(r)||'—'}</b></td><td><b class="risk-score">${riskScore(r,true)||'—'}</b></td><td>${fmtDate(r.data?.review_date)}</td><td><span class="badge ${esc(r.status)}">${esc(statusLabels[r.status]||r.status)}</span></td></tr>`).join('')}else if(module==='audits'){head='<th>MÃ</th><th>CUỘC ĐÁNH GIÁ</th><th>NGÀY</th><th>ĐIỀU KHOẢN</th><th>CHUYÊN GIA</th><th>ĐỘC LẬP</th><th>TRẠNG THÁI</th>';body=rows.map(r=>`<tr data-record="${r.id}"><td><span class="code">${esc(r.code||'#'+r.id)}</span></td><td><strong>${esc(r.title)}</strong></td><td>${fmtDate(r.data?.audit_date)}</td><td>${esc(r.data?.clauses||'—')}</td><td>${esc(r.data?.auditor||'—')}</td><td>${r.data?.independence==='confirmed'?'Đã xác nhận':'Chưa xác nhận'}</td><td><span class="badge ${esc(r.status)}">${esc(statusLabels[r.status]||r.status)}</span></td></tr>`).join('')}else if(module==='nc'){head='<th>MÃ</th><th>PHÁT HIỆN / SỰ KHÔNG PHÙ HỢP</th><th>NGUỒN</th><th>ĐIỀU KHOẢN</th><th>PHỤ TRÁCH</th><th>HẠN</th><th>TRẠNG THÁI</th>';body=rows.map(r=>`<tr data-record="${r.id}"><td><span class="code">${esc(r.code||'#'+r.id)}</span></td><td><strong>${esc(r.title)}</strong></td><td>${esc(r.data?.source_type||'—')}</td><td>${esc(r.data?.clause||'—')}</td><td>${esc(r.owner_name||'—')}</td><td>${fmtDate(r.due_date)}</td><td><span class="badge ${esc(r.status)}">${esc(statusLabels[r.status]||r.status)}</span></td></tr>`).join('')}else if(module==='capa'){head='<th>MÃ</th><th>HÀNH ĐỘNG KHẮC PHỤC</th><th>NGUYÊN NHÂN GỐC</th><th>HẠN HIỆU LỰC</th><th>KẾT QUẢ HIỆU LỰC</th><th>TIẾN ĐỘ</th><th>TRẠNG THÁI</th>';body=rows.map(r=>{const res=r.data?.effectiveness_result;return `<tr data-record="${r.id}"><td><span class="code">${esc(r.code||'#'+r.id)}</span></td><td><strong>${esc(r.title)}</strong><div class="meta">${esc((r.data?.corrective_action||r.description||'').slice(0,85))}</div></td><td>${esc((r.data?.root_cause||'—').slice(0,65))}</td><td>${fmtDate(r.data?.effectiveness_due)}</td><td><span class="effectiveness ${res||'pending'}">${res==='effective'?'Đạt':res==='partial'?'Một phần':res==='not_effective'?'Chưa đạt':'Chưa đánh giá'}</span></td><td>${r.progress}%</td><td><span class="badge ${esc(r.status)}">${esc(statusLabels[r.status]||r.status)}</span></td></tr>`}).join('')}else{head='<th>MÃ</th><th>KỲ XEM XÉT</th><th>NGÀY HỌP</th><th>CHỦ TRÌ</th><th>ĐẦU VÀO SẴN SÀNG</th><th>TRẠNG THÁI</th>';body=rows.map(r=>`<tr data-record="${r.id}"><td><span class="code">${esc(r.code||'#'+r.id)}</span></td><td><strong>${esc(r.title)}</strong><div class="meta">${esc(r.data?.review_period_from||'—')} → ${esc(r.data?.review_period_to||'—')}</div></td><td>${fmtDate(r.data?.meeting_date)}</td><td>${esc(r.data?.chair||'—')}</td><td><b>${esc(r.data?.input_readiness_pct??'—')}${r.data?.input_readiness_pct!==undefined?'%':''}</b></td><td><span class="badge ${esc(r.status)}">${esc(statusLabels[r.status]||r.status)}</span></td></tr>`).join('')};const mrBlock=module==='meetings'&&mr?`<section class="card mr-input-card"><div class="home-section-title"><span class="section-symbol">${iconSvg('meetings')}</span><div><small>ĐẦU VÀO THEO 8.9.2</small><h3>Mức sẵn sàng dữ liệu hệ thống</h3></div><strong>${mr.readiness_pct}%</strong></div><div class="mr-input-grid">${(mr.inputs||[]).map(x=>`<div class="mr-input ${x.readiness}"><span>${x.readiness==='ready'?'✓':'!'}</span><div><strong>${esc(x.label)}</strong><small>${esc(x.source)} · ${x.count} bản ghi</small></div></div>`).join('')}</div></section>`:'';$('#content').innerHTML=`<section class="card qms-hero compact"><div><span class="eyebrow">QUẢN LÝ CHẤT LƯỢNG</span><h2>${esc(moduleMeta[module].label)}</h2><p>${module==='risks'?'Nhận diện → đánh giá → kiểm soát → xem xét rủi ro còn lại.':module==='audits'?'Lập kế hoạch → thực hiện đánh giá → xử lý phát hiện → lưu bằng chứng.':module==='nc'?'Kiểm soát sự không phù hợp → xác định nguyên nhân → thực hiện khắc phục.':module==='capa'?'Phân tích nguyên nhân → khắc phục → bằng chứng → đánh giá hiệu lực.':'Chuẩn bị đầu vào → kết luận → giao hành động → theo dõi hoàn thành.'}</p></div></section><div class="qms-kpi-grid">${kpis}</div>${mrBlock}<div class="toolbar"><div class="toolbar-left">${statusTabs()}</div><div class="toolbar-right"><input class="list-search-input" id="listSearchInput" value="${esc(state.query)}" placeholder="Lọc danh sách…"><span class="panel-sub">${rows.length} bản ghi</span>${canManage(module)?'<button class="btn primary small" id="inlineNew">＋ Tạo mới</button>':''}</div></div><div class="card table-card"><table class="data-table qms-table"><thead><tr>${head}</tr></thead><tbody>${body||`<tr><td colspan="8" class="empty">Chưa có bản ghi.</td></tr>`}</tbody></table></div>`;$$('[data-status]').forEach(b=>b.onclick=()=>{state.status=b.dataset.status;renderQualityModule(module)});$$('[data-record]').forEach(x=>x.onclick=()=>openRecord(+x.dataset.record));let t;$('#listSearchInput')?.addEventListener('input',e=>{clearTimeout(t);state.query=e.target.value;t=setTimeout(()=>renderQualityModule(module),280)});$('#inlineNew')?.addEventListener('click',newRecord)}
function lessonSourcesHtml(lesson){const links=(lesson.source_links||[]).filter(x=>x&&/^https:\/\//i.test(x.url||''));if(!links.length)return '<div class="note">Chưa gắn nguồn tham khảo bổ sung cho bài này.</div>';return `<div class="learning-source-links rich">${links.map(x=>`<a class="learning-source-link" href="${esc(x.url)}" target="_blank" rel="noopener"><span>${esc(x.kind||'Tài liệu tham khảo')}</span><strong>${esc(x.title||x.url)}</strong><small>${esc(x.organization||'')}${x.year?` · ${esc(x.year)}`:''}</small></a>`).join('')}</div>`}
function lessonConceptsHtml(lesson){const rows=lesson.concepts||[];if(!rows.length)return '';return `<section class="lesson-concepts"><h4>Khái niệm cần hiểu</h4><div class="lesson-concept-grid">${rows.map(x=>{const example=String(x.example||'').replace(/^\s*Ví dụ\s*:\s*/i,'').trim();return `<article class="lesson-concept-card"><strong>${esc(x.term||'')}</strong><p>${esc(x.definition||'')}</p>${example?`<div><b>Ví dụ:</b> ${esc(example)}</div>`:''}</article>`}).join('')}</div></section>`}
function lessonHtml(lesson){
 const q=(lesson.questions||[]).map((x,qi)=>`<fieldset class="quiz-question" data-q="${qi}"><legend>${qi+1}. ${esc(x.q)}</legend>${(x.options||[]).map((o,oi)=>`<label><input type="radio" name="q${qi}" value="${oi}"> <span>${esc(o)}</span></label>`).join('')}<div class="quiz-feedback" data-quiz-feedback="${qi}" hidden></div></fieldset>`).join('');
 const intro=[lesson.overview,lesson.why_it_matters].filter(Boolean).map(x=>`<p>${esc(x)}</p>`).join('');
 return `<div class="knowledge-detail course-lesson lesson-reader-v2">
  <div class="lesson-meta"><span>${lesson.duration||5} phút</span><span>${lesson.progress?.status==='completed'?'Đã hoàn thành':lesson.progress?.status==='in_progress'?'Đang học':'Chưa bắt đầu'}</span>${lesson.progress?.score!==null&&lesson.progress?.score!==undefined?`<span>Kết quả gần nhất ${lesson.progress.score}%</span>`:''}</div>
  <div class="clause-row">${(lesson.clauses||[]).map(c=>`<span class="clause-chip">${esc(c)}</span>`).join('')}</div>
  <section class="lesson-objectives"><h4>Sau bài này, bạn có thể</h4>${listHtml(lesson.objectives)}</section>
  <section class="lesson-explainer">${intro}</section>
  ${lessonConceptsHtml(lesson)}
  ${(lesson.key_points||[]).length?`<section><h4>Điểm cần nhớ</h4>${listHtml(lesson.key_points)}</section>`:''}
  ${lesson.step_by_step?.length?`<section class="practice-box"><h4>Cách làm từng bước</h4><ol>${lesson.step_by_step.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>`:''}
  ${lesson.decision_table?.length?`<section><h4>Bảng quyết định</h4>${decisionTableHtml(lesson.decision_table)}</section>`:''}
  ${lesson.examples?.length?`<section class="example-box"><h4>Ví dụ</h4>${listHtml(lesson.examples)}</section>`:''}
  ${(lesson.common_mistakes?.length||lesson.cautions?.length)?`<section class="attention-box lesson-pitfalls"><h4>Lưu ý</h4>${listHtml(uniqueTextItems([...(lesson.common_mistakes||[]),...(lesson.cautions||[])]))}</section>`:''}
  <section class="practice-box"><h4>Áp dụng tại Khoa Xét nghiệm</h4><ol>${(lesson.practice||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>
  <section class="evidence-box"><h4>Hồ sơ liên quan</h4>${listHtml(lesson.evidence)}</section>
  ${lesson.case?`<section class="case-box"><h4>Tình huống</h4><p>${esc(lesson.case)}</p></section>`:''}
  <section class="quiz-section"><h4>Tự kiểm tra</h4><form id="quizForm">${q}<div id="quizSummary" class="quiz-summary" hidden></div><div class="form-actions"><button class="btn primary" id="quizCheckBtn">Kiểm tra đáp án</button></div></form></section>
  ${lesson.reference_note?`<p class="course-source-note">${esc(lesson.reference_note)}</p>`:''}
  <details class="lesson-sources"><summary>Nguồn tham khảo</summary>${lessonSourcesHtml(lesson)}</details>
 </div>`}
function wireLessonQuiz(lesson){const form=$('#quizForm');if(!form)return;form.addEventListener('submit',async e=>{e.preventDefault();let correct=0,answered=0,total=(lesson.questions||[]).length;(lesson.questions||[]).forEach((q,qi)=>{const field=form.querySelector(`[data-q="${qi}"]`),checked=form.querySelector(`input[name=q${qi}]:checked`),feedback=form.querySelector(`[data-quiz-feedback="${qi}"]`);field?.classList.remove('quiz-correct','quiz-incorrect','quiz-unanswered');if(!checked){field?.classList.add('quiz-unanswered');if(feedback){feedback.hidden=false;feedback.className='quiz-feedback quiz-feedback-warning';feedback.innerHTML='<strong>Chưa trả lời</strong><p>Chọn một đáp án rồi kiểm tra lại.</p>'}return}answered++;const selected=+checked.value,isCorrect=selected===+q.answer;if(isCorrect)correct++;field?.classList.add(isCorrect?'quiz-correct':'quiz-incorrect');if(feedback){const correctText=esc((q.options||[])[q.answer]||'');const explanation=esc(q.explanation||'Xem lại phần nội dung cốt lõi của bài học.');feedback.hidden=false;feedback.className=`quiz-feedback ${isCorrect?'quiz-feedback-correct':'quiz-feedback-incorrect'}`;feedback.innerHTML=`<strong>${isCorrect?'✓ Đúng':'✕ Chưa đúng'}</strong>${isCorrect?'':`<p><b>Đáp án đúng:</b> ${correctText}</p>`}<p>${explanation}</p>`}});const score=total?Math.round(correct/total*100):100;const summary=$('#quizSummary');if(summary){summary.hidden=false;summary.className=`quiz-summary ${score===100?'success':score>=60?'partial':'retry'}`;summary.innerHTML=`<strong>${correct}/${total} câu đúng · ${score}%</strong><span>${score===100?'Bạn đã nắm tốt nội dung bài học.':answered<total?'Hãy trả lời đủ các câu và kiểm tra lại.':'Xem phần giải thích ở từng câu rồi thử lại.'}</span>`}try{const status=score===100?'completed':'in_progress';await api(`knowledge/learning/${encodeURIComponent(lesson.slug)}/progress`,{method:'POST',json:{status,score}});lesson.progress={...(lesson.progress||{}),status,score};toast(score===100?'Đã hoàn thành bài học':`Đã lưu kết quả ${score}%`)}catch(err){toast(err.message,'err')}})}
function moduleProgress(lessons){const done=lessons.filter(x=>x.progress?.status==='completed').length;return {done,total:lessons.length,pct:lessons.length?Math.round(done/lessons.length*100):0}}
async function renderLearning(){
 const data=await api('knowledge/learning');const lessons=data.lessons||[];const pct=data.total?Math.round((data.completed||0)/data.total*100):0;
 const groups=[];const by={};lessons.sort((a,b)=>(a.order||0)-(b.order||0)).forEach(l=>{const k=l.module||'M0';if(!by[k]){by[k]={key:k,title:l.module_title||'Chuyên đề',intro:l.module_intro||'',common_mistakes:l.module_common_mistakes||[],lessons:[]};groups.push(by[k])}by[k].lessons.push(l)});
 const tones=['green','blue','amber','violet'];
 const roadmap=groups.map((g,i)=>{const p=moduleProgress(g.lessons),tone=tones[i%tones.length];return `<button class="course-module-jump tone-${tone}" data-module-jump="${esc(g.key)}"><b>${i+1}</b><span><strong>${esc(g.title)}</strong><small>${p.done}/${p.total} bài · ${p.pct}%</small></span><i style="--p:${p.pct}%"></i></button>`}).join('');
 const sections=groups.map((g,gi)=>{const p=moduleProgress(g.lessons),tone=tones[gi%tones.length];const cards=g.lessons.map((l,i)=>{const done=l.progress?.status==='completed',featured=i===0;return `<button class="lesson-card tone-${tone} ${featured?'featured':''} ${done?'completed':''}" data-lesson-slug="${esc(l.slug)}"><span class="lesson-accent"></span><div class="lesson-card-index"><b>${String(i+1).padStart(2,'0')}</b><small>${l.duration||5} phút</small></div><div class="lesson-card-copy"><div class="lesson-top"><span>${esc((l.clauses||[]).slice(0,2).join(' · ')||'ISO 15189')}</span><span class="lesson-status">${done?'✓ Đã học':'Mở bài'}</span></div><strong>${esc(l.title)}</strong><div class="lesson-card-foot"><span>${done?'Hoàn thành':'Chưa hoàn thành'}</span><div class="lesson-progress"><i style="width:${done?100:0}%"></i></div><em>›</em></div></div></button>`}).join('');return `<section class="course-module course-tone-${tone}" id="course-${esc(g.key)}"><div class="course-module-head"><div class="course-module-heading"><span class="course-part-no">${String(gi+1).padStart(2,'0')}</span><div><h3>${esc(g.title)}</h3></div></div><div class="module-score"><strong>${p.pct}%</strong><span>${p.done}/${p.total} bài</span></div></div>${g.common_mistakes?.length?`<div class="attention-box lesson-pitfalls"><h4>Lưu ý</h4>${listHtml(g.common_mistakes)}</div>`:''}<div class="learning-grid">${cards}</div></section>`}).join('');
 $('#content').innerHTML=`<section class="module-simple-head learning-module-head"><div><h2>Lớp học TCVN ISO 15189:2025</h2><span>${data.completed||0}/${data.total||0} bài hoàn thành · ${pct}%</span></div></section><section class="card course-map course-map-compact"><div class="course-roadmap">${roadmap}</div></section>${sections}`;
 $$('[data-module-jump]').forEach(b=>b.onclick=()=>document.getElementById('course-'+b.dataset.moduleJump)?.scrollIntoView({behavior:'smooth',block:'start'}));
 $$('[data-lesson-slug]').forEach(b=>b.onclick=()=>{const l=lessons.find(x=>x.slug===b.dataset.lessonSlug);if(!l)return;openDrawer(l.title,'learning',lessonHtml(l),{layout:'modal'});wireLessonQuiz(l)})
}
function formTemplateHtml(t){const cols=t.columns||[],fields=t.fields||[];const blank=cols.length?Array.from({length:5},(_,i)=>`<tr><td>${i+1}</td>${cols.map(()=>'<td>&nbsp;</td>').join('')}</tr>`).join(''):fields.map(f=>`<tr><th>${esc(f.label||f.name)}</th><td>&nbsp;</td></tr>`).join('');return `<article class="iso-form-a4" id="formTemplateA4"><header class="iso-form-header"><div><strong>BỆNH VIỆN HỮU NGHỊ ĐA KHOA NGHỆ AN - GIAI ĐOẠN 2</strong><span>KHOA XÉT NGHIỆM · HỆ THỐNG QUẢN LÝ CHẤT LƯỢNG</span></div><div class="iso-form-control"><b>${esc(t.id||'')}</b><span>Phiên bản: ____</span><span>Ngày hiệu lực: ____/____/______</span></div></header><h1>${esc(t.title||'')}</h1><div class="form-template-meta"><p><b>Điều khoản tham chiếu:</b> ${esc((t.clauses||[]).join(', '))}</p><p><b>Mục đích:</b> ${esc(t.purpose||'')}</p></div>${(t.sections||[]).length?`<section><h3>Nội dung cần ghi nhận</h3><ol>${(t.sections||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>`:''}<section><h3>Bảng ghi nhận</h3><div class="table-card"><table class="data-table form-template-table">${cols.length?`<thead><tr><th>STT</th>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead>`:''}<tbody>${blank}</tbody></table></div></section><section class="form-signatures"><div>Người lập/Thực hiện<br><br><br>____________</div><div>Người rà soát<br><br><br>____________</div><div>Người phê duyệt<br><br><br>____________</div></section><footer class="iso-form-footer"><span>${esc(t.id||'')} · Phiên bản ____ · Trang 1/1</span></footer></article>`}

function openFormTemplate(t){openDrawer(`${t.id} · ${t.title}`,'toolkit',`<div class="export-toolbar"><button class="btn small" id="printFormTemplate">In A4</button><button class="btn small" id="pdfFormTemplate">PDF A4</button><button class="btn primary small" id="docxFormTemplate">DOCX A4</button></div>${formTemplateHtml(t)}`,{layout:'modal'});$('#printFormTemplate')?.addEventListener('click',()=>{auditUiEvent('print_a4',{module:'forms',template_id:t.id,title:t.title});printElementA4($('#formTemplateA4'))});$('#pdfFormTemplate')?.addEventListener('click',()=>exportElementPdf($('#formTemplateA4'),`${t.id}.pdf`,{action:'form_export',module:'forms',template_id:t.id,title:t.title}));$('#docxFormTemplate')?.addEventListener('click',()=>exportElementDocx($('#formTemplateA4'),`${t.id}.docx`,t.title,{action:'form_export',module:'forms',template_id:t.id,title:t.title}))}
async function renderToolkit(force=false){const data=await api(`knowledge/sources${force?'?refresh=1':''}`);const snap=data.snapshot||{};const progress=snap.progress_summary||{};const rows=sourceRows(data.items||[]);const archives=(data.archives||[]).map(a=>`<div class="archive-item"><strong>${esc(a.name)}</strong><small>${esc(a.archive)} · ${esc(a.category||'')}</small></div>`).join('');const procs=(data.procedures||[]).filter(x=>x.order).map(x=>{const complete=!!String(x.code||'').trim();const status=complete?'Có mã tài liệu':'Chưa có mã';return `<tr><td>${esc(x.order)}</td><td><span class="code">${esc(x.code||'Chưa có mã')}</span></td><td><strong>${esc(x.title)}</strong>${x.note?`<small class="source-path">${esc(x.note)}</small>`:''}</td><td>${esc(x.iso||'—')}</td><td>${esc(x.qd2429||'—')}</td><td><span class="status ${complete?'done':'open'}">${status}</span></td></tr>`}).join('');const forms=(data.recordsCatalog||[]).filter(x=>x.order).map(x=>`<tr><td>${esc(x.order)}</td><td><strong>${esc(x.title)}</strong></td><td>${esc(x.iso||'—')}</td><td>${esc(x.qd2429||'—')}</td><td>${esc(x.retention||'Chưa cập nhật')}</td></tr>`).join('');const templates=(data.formTemplates||[]).map((t,i)=>`<button class="form-template-card" data-form-template="${i}"><span class="code">${esc(t.id||'')}</span><strong>${esc(t.title||'')}</strong><small>ISO ${esc((t.clauses||[]).join(', '))}</small><p>${esc(t.purpose||'')}</p><em>PDF A4 · DOCX A4 →</em></button>`).join('');const summary=summaryCardsHtml(progress.summary_cards||[],'toolkit-overview-cards');const progressRows=progressGroupRows(progress.current_groups||[]);$('#content').innerHTML=`<section class="card knowledge-hero compact"><div><span class="eyebrow">THƯ VIỆN TCVN ISO 15189:2025</span><h2>Quy trình, biểu mẫu và tài liệu hướng dẫn</h2><p>Tài liệu phục vụ học tập, triển khai, giám sát và thực hành hệ thống quản lý chất lượng tại Khoa Xét nghiệm.</p></div></section>${summary?`<section class="card panel"><div class="panel-head"><div><h3>Tổng quan khối lượng tài liệu</h3><div class="panel-sub">Cập nhật theo báo cáo tiến độ ngày ${fmtDate(progress.report_date||'')}</div></div></div>${summary}</section>`:''}${progressRows?`<section class="card panel"><div class="panel-head"><div><h3>Tiến độ đang xây dựng</h3><div class="panel-sub">Theo dõi từng nhóm tài liệu để Trưởng khoa và Lãnh đạo Bệnh viện giám sát.</div></div></div><div class="table-card"><table class="data-table"><thead><tr><th>NHÓM TÀI LIỆU</th><th>NGÀY GIAO</th><th>HẠN SAU RÀ SOÁT</th><th>TRẠNG THÁI</th><th>RÀ SOÁT</th><th>GHI CHÚ</th></tr></thead><tbody>${progressRows}</tbody></table></div></section>`:''}<section class="card panel"><div class="panel-head"><div><h3>Bộ biểu mẫu kiểm soát theo ISO · A4</h3><div class="panel-sub">Mẫu nội bộ NAH cho giám sát, kế hoạch, đánh giá, hành động khắc phục, rủi ro, phương pháp, kiểm soát chất lượng và báo cáo. ISO không quy định một mẫu A4 duy nhất; hệ thống chuẩn hóa trường kiểm soát tài liệu và cho phép xuất PDF/DOCX.</div></div><span class="badge active">${data.formTemplates?.length||0} mẫu</span></div><div class="form-template-grid">${templates||'<div class="empty">Chưa có mẫu.</div>'}</div></section><div class="toolbar"><div class="source-filter"><input id="sourceSearch" placeholder="Tìm tên tài liệu, đường dẫn, nhóm, điều khoản…"><span id="sourceCount">${(data.items||[]).filter(x=>!x.isFolder).length} tệp đang hiển thị</span></div>${state.boot.user.isWpAdmin?'<button class="btn small" id="refreshSources">Quét lại Google Drive</button>':''}</div>${data.connected?'':`<div class="note"><strong>Thư viện nội bộ vẫn sẵn sàng.</strong> ${esc(data.error||'Nguồn Google Drive hiện chưa khả dụng.')}${state.boot.user.isWpAdmin?' Có thể kết nối lại Google Drive trong Cài đặt khi cần truy cập tệp nguồn trực tuyến.':''}</div>`}<section class="card table-card source-table"><table class="data-table"><thead><tr><th>TÀI LIỆU NGUỒN</th><th>NHÓM</th><th>ISO</th><th>MỞ</th></tr></thead><tbody id="sourceTbody">${rows||'<tr><td colspan="4" class="empty">Chưa đọc được tệp nguồn.</td></tr>'}</tbody></table></section><details class="card toolkit-section" open><summary>Danh mục quy trình ISO · ${(data.procedures||[]).filter(x=>x.order).length}</summary><div class="table-card"><table class="data-table"><thead><tr><th>STT</th><th>MÃ</th><th>TÊN TÀI LIỆU</th><th>ISO</th><th>QĐ 2429</th><th>TRẠNG THÁI</th></tr></thead><tbody>${procs}</tbody></table></div></details><details class="card toolkit-section"><summary>Danh mục hồ sơ cần kiểm soát · ${(data.recordsCatalog||[]).filter(x=>x.order).length}</summary><div class="table-card"><table class="data-table"><thead><tr><th>STT</th><th>TÊN BIỂU MẪU / HỒ SƠ</th><th>ISO</th><th>QĐ 2429</th><th>LƯU GIỮ</th></tr></thead><tbody>${forms}</tbody></table></div></details><details class="card toolkit-section"><summary>Tài liệu tham khảo bổ sung · ${data.archives?.length||0}</summary><div class="archive-grid">${archives}</div></details>`;const filter=()=>{const q=($('#sourceSearch').value||'').trim().toLowerCase();let n=0;$$('[data-source-row]').forEach(r=>{const show=!q||r.dataset.hay.includes(q);r.hidden=!show;if(show)n++});$('#sourceCount').textContent=`${n} tệp đang hiển thị`};$('#sourceSearch').oninput=filter;$('#refreshSources')?.addEventListener('click',()=>renderToolkit(true));$$('[data-form-template]').forEach(b=>b.onclick=()=>openFormTemplate((data.formTemplates||[])[+b.dataset.formTemplate]))}
const staffCapLabels={edit_assigned_iso:'Cập nhật tiêu chí ISO được giao',manage_documents:'Quy trình, tài liệu & biểu mẫu',manage_evidence:'Hồ sơ & bằng chứng',manage_tasks:'Công việc được giao',manage_indicators:'Chỉ số chất lượng',manage_incidents:'Sự cố',manage_risks:'Rủi ro',manage_nc:'Sự không phù hợp & khắc phục',export:'Xuất báo cáo',comment:'Trao đổi',upload:'Tải bằng chứng'};
function teamPermissionHtml(team,u={}){const safe=(team.safeCaps||[]).filter(x=>x!=='access');const custom=u.permissionMode==='custom';const perms=u.permissions||{};return `<div class="field full"><label class="switch-line"><input type="checkbox" id="staffCustomPermissions" ${custom?'checked':''}> <strong>Tùy chỉnh quyền cho tài khoản này</strong></label><div class="staff-permission-grid">${safe.map(cap=>`<label class="staff-permission"><input type="checkbox" data-staff-cap="${esc(cap)}" ${perms[cap]!==false?'checked':''} ${custom?'':'disabled'}><span>${esc(staffCapLabels[cap]||cap)}</span></label>`).join('')}</div></div>`}
function teamUserFormHtml(team,u={}){return `<form id="teamUserForm"><div class="form-grid"><div class="field"><label>Họ tên *</label><input name="display_name" required value="${esc(u.name||'')}"></div><div class="field"><label>Tên đăng nhập *</label><input name="username" required value="${esc(u.username||'')}" autocomplete="off"></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(u.email||'')}"></div><div class="field"><label>${u.id?'Mật khẩu mới':'Mật khẩu *'}</label><input name="password" type="password" ${u.id?'':'required'} autocomplete="new-password" placeholder="${u.id?'Để trống nếu không đổi':'Tối thiểu 10 ký tự'}"></div><div class="field full"><label><input style="width:auto" type="checkbox" name="is_active" ${u.id?(u.isActive?'checked':''):'checked'}> Tài khoản đang hoạt động</label></div>${teamPermissionHtml(team,u)}</div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">${u.id?'Lưu thay đổi':'Tạo tài khoản nhân viên'}</button></div></form>`}
function openTeamUserForm(team,u={}){openDrawer(u.id?'Cập nhật nhân viên':'Thêm nhân viên Khoa Xét nghiệm','team',teamUserFormHtml(team,u),{layout:'modal'});const f=$('#teamUserForm');$('[data-close]',f).onclick=closeDrawer;const custom=$('#staffCustomPermissions',f);const sync=()=>$$('[data-staff-cap]',f).forEach(c=>c.disabled=!custom.checked);custom.onchange=sync;sync();f.onsubmit=async e=>{e.preventDefault();const fd=new FormData(f);const data=Object.fromEntries(fd.entries());data.is_active=f.is_active.checked;data.permission_mode=custom.checked?'custom':'inherit';data.permissions={};$$('[data-staff-cap]',f).forEach(c=>data.permissions[c.dataset.staffCap]=c.checked);if(!data.password)delete data.password;try{if(u.id)await api(`team/users/${u.id}`,{method:'PATCH',json:data});else await api('team/users',{method:'POST',json:data});toast(u.id?'Đã cập nhật nhân viên':'Đã tạo tài khoản nhân viên');closeDrawer();await refreshBootstrapLight();await renderTeam()}catch(err){toast(err.message,'err')}}}
function workloadStatusClass(s){return ['done','closed','approved'].includes(s)?'done':s==='review'?'review':'in_progress'}
async function openTeamMember(id){try{const data=await api(`team/users/${id}/workload`),u=data.user||{},rows=data.workload||[];const stats=u.stats||{};const work=rows.map(x=>`<tr ${x.canOpen?`data-record="${x.id}"`:''} class="${x.canOpen?'':'readonly-row'}"><td><strong>${esc(x.title)}</strong><div class="meta">${esc(moduleMeta[x.module]?.label||x.module)}${x.code?' · '+esc(x.code):''}</div></td><td>${x.assignment_role==='lead'?'Phụ trách chính':'Phối hợp'}</td><td><span class="badge ${esc(workloadStatusClass(x.status))}">${esc(statusLabels[x.status]||x.status)}</span></td><td><div class="progress"><span style="width:${Math.max(0,Math.min(100,x.progress||0))}%"></span></div><small>${x.progress||0}%</small></td><td>${fmtDate(x.due_date)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Chưa có công việc được phân công.</td></tr>';const buttons=state.boot.user.isWpAdmin||hasCap('manage_lab_staff')?`<div class="form-actions team-member-actions">${u.role==='lab_staff'?`<button class="btn" id="editTeamMember">Sửa tài khoản & quyền</button><button class="btn danger" id="deleteTeamMember">Xóa / ngừng tài khoản</button>`:''}</div>`:'';openDrawer(u.name||'Nhân sự Khoa Xét nghiệm','team',`<div class="team-member-detail"><div class="team-member-summary"><div class="team-avatar large">${esc((u.name||'N').charAt(0).toUpperCase())}</div><div><h3>${esc(u.name||'')}</h3><p>${esc(u.roleLabel||'')} · ${esc(u.department||'Khoa Xét nghiệm')}</p></div></div><div class="team-kpis compact"><div><small>Đang thực hiện</small><strong>${stats.active||0}</strong></div><div><small>Quá hạn</small><strong>${stats.overdue||0}</strong></div><div><small>Phụ trách chính</small><strong>${stats.lead||0}</strong></div><div><small>Tiến độ TB</small><strong>${stats.avgProgress||0}%</strong></div></div><div class="section-title">Công việc được phân công</div><div class="table-card"><table class="data-table"><thead><tr><th>CÔNG VIỆC</th><th>VAI TRÒ</th><th>TRẠNG THÁI</th><th>TIẾN ĐỘ</th><th>THỜI HẠN</th></tr></thead><tbody>${work}</tbody></table></div>${buttons}</div>`,{layout:'modal'});$$('[data-record]',$('#drawerBody')).forEach(x=>x.onclick=()=>{closeDrawer();openRecord(+x.dataset.record)});$('#editTeamMember')?.addEventListener('click',async()=>{closeDrawer();const team=await api('team');openTeamUserForm(team,u)});$('#deleteTeamMember')?.addEventListener('click',async()=>{if(!confirm(`Xóa hoặc ngừng tài khoản ${u.name}?`))return;try{const out=await api(`team/users/${u.id}`,{method:'DELETE'});toast(out.archived?'Đã ngừng tài khoản để bảo toàn lịch sử':'Đã xóa tài khoản');closeDrawer();await refreshBootstrapLight();await renderTeam()}catch(err){toast(err.message,'err')}})}catch(e){toast(e.message,'err')}}
async function renderTeam(){const data=await api('team');const totals=data.totals||{};const rows=(data.members||[]).map(u=>`<tr class="team-row ${u.isActive?'':'inactive'}" data-team-member="${u.id}"><td><div class="team-person"><span class="team-avatar">${esc((u.name||'N').charAt(0).toUpperCase())}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.roleLabel||'')}${u.isActive?'':' · Ngừng hoạt động'}</small></div></div></td><td>${u.stats.active||0}</td><td><strong class="${u.stats.overdue?'text-danger':''}">${u.stats.overdue||0}</strong></td><td>${u.stats.due7||0}</td><td>${u.stats.lead||0}</td><td><div class="team-progress-cell"><div class="progress"><span style="width:${Math.max(0,Math.min(100,u.stats.avgProgress||0))}%"></span></div><b>${u.stats.avgProgress||0}%</b></div></td><td>${u.stats.supportRequests||0}</td><td>${u.stats.lastUpdate?esc(u.stats.lastUpdate):'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Chưa có tài khoản nhân sự Khoa Xét nghiệm.</td></tr>';$('#content').innerHTML=`<section class="card module-hero team-hero"><div><span class="eyebrow">KHOA XÉT NGHIỆM</span><h2>Nhân sự & phân công công việc</h2><p>Theo dõi người phụ trách, người phối hợp, thời hạn, tiến độ và các nội dung cần hỗ trợ.</p></div>${data.canManage?'<button class="btn primary" id="addTeamMember">＋ Thêm nhân viên</button>':''}</section><section class="team-kpis"><div class="card"><small>Nhân viên</small><strong>${totals.staff||0}</strong><span>Tài khoản Khoa Xét nghiệm</span></div><div class="card"><small>Đang thực hiện</small><strong>${totals.activeTasks||0}</strong><span>Công việc chưa hoàn tất</span></div><div class="card danger"><small>Quá hạn</small><strong>${totals.overdue||0}</strong><span>Cần ưu tiên xử lý</span></div><div class="card warning"><small>Sắp đến hạn</small><strong>${totals.due7||0}</strong><span>Trong 7 ngày</span></div><div class="card support"><small>Đề nghị hỗ trợ</small><strong>${totals.supportRequests||0}</strong><span>Từ cập nhật tiến độ</span></div></section><section class="card panel"><div class="panel-head"><div><h3>Khối lượng công việc theo nhân sự</h3><div class="panel-sub">Bấm vào tên nhân viên để xem danh sách công việc và tiến độ chi tiết.</div></div><button class="btn small" data-go="tasks">Mở danh sách công việc</button></div><div class="table-card"><table class="data-table team-table"><thead><tr><th>NHÂN SỰ</th><th>ĐANG LÀM</th><th>QUÁ HẠN</th><th>7 NGÀY</th><th>PHỤ TRÁCH CHÍNH</th><th>TIẾN ĐỘ TB</th><th>CẦN HỖ TRỢ</th><th>CẬP NHẬT GẦN NHẤT</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;$('#addTeamMember')?.addEventListener('click',()=>openTeamUserForm(data));$$('[data-team-member]').forEach(x=>x.onclick=()=>openTeamMember(+x.dataset.teamMember));$$('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go))}

const competencyItemTypeLabels={role:'Năng lực chung',process:'Quá trình',test:'Xét nghiệm/phương pháp',equipment:'Thiết bị',system:'Hệ thống thông tin',quality:'Kiểm soát chất lượng',authorization:'Hoạt động cần ủy quyền'};
const competencyStatusLabels={competent:'Đạt năng lực',assessment_due:'Đến hạn đánh giá',expired:'Hết hạn ủy quyền',not_competent:'Chưa đạt',in_training:'Đang đào tạo'};
function competencyStatusClass(s){return s==='competent'?'done':s==='expired'||s==='not_competent'?'critical':s==='assessment_due'?'warning':'in_progress'}
function competencyItemFormHtml(item={}){return `<form id="competencyItemForm"><div class="form-grid"><div class="field"><label>Mã năng lực *</label><input name="code" required value="${esc(item.code||'')}"></div><div class="field"><label>Nhóm năng lực</label><select name="item_type">${Object.entries(competencyItemTypeLabels).map(([k,v])=>`<option value="${k}" ${item.item_type===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field full"><label>Tên năng lực *</label><input name="title" required value="${esc(item.title||'')}"></div><div class="field"><label>Điều khoản ISO liên quan</label><input name="iso_clause" value="${esc(item.iso_clause||'')}"></div><div class="field"><label>Chu kỳ đánh giá (tháng)</label><input type="number" min="1" max="60" name="assessment_frequency_months" value="${esc(item.assessment_frequency_months||12)}"></div><div class="field"><label>Thời hạn ủy quyền (tháng)</label><input type="number" min="1" max="60" name="authorization_valid_months" value="${esc(item.authorization_valid_months||12)}"></div><div class="field full"><label>Mô tả năng lực</label><textarea name="description">${esc(item.description||'')}</textarea></div><div class="field full"><label>Đào tạo cần hoàn thành</label><textarea name="required_training">${esc(item.required_training||'')}</textarea></div><div class="field full"><label><input style="width:auto" type="checkbox" name="is_active" ${item.id?(item.is_active?'checked':''):'checked'}> Đang sử dụng</label></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">${item.id?'Lưu thay đổi':'Tạo tiêu chí năng lực'}</button></div></form>`}
function openCompetencyItemForm(data,item={}){openDrawer(item.id?'Cập nhật tiêu chí năng lực':'Thêm tiêu chí năng lực','competency',competencyItemFormHtml(item),{layout:'modal'});const f=$('#competencyItemForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f).entries());d.is_active=f.is_active.checked;try{if(item.id)await api(`competency/items/${item.id}`,{method:'PATCH',json:d});else await api('competency/items',{method:'POST',json:d});toast(item.id?'Đã cập nhật tiêu chí năng lực':'Đã thêm tiêu chí năng lực');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}}}
function competencyAssignFormHtml(data,memberRef=''){return `<form id="competencyAssignForm"><div class="form-grid"><div class="field"><label>Nhân viên *</label><select name="user_ref" required><option value="">Chọn nhân viên</option>${(data.members||[]).filter(x=>x.isActive).map(x=>`<option value="${esc(x.ref)}" ${memberRef===x.ref?'selected':''}>${esc(x.name)} — ${esc(x.roleLabel)}</option>`).join('')}</select></div><div class="field"><label>Năng lực *</label><select name="competency_id" required><option value="">Chọn nội dung</option>${(data.items||[]).filter(x=>x.is_active).map(x=>`<option value="${x.id}">${esc(x.code)} · ${esc(x.title)}</option>`).join('')}</select></div><div class="field"><label>Mức yêu cầu</label><input name="required_level" value="Đạt yêu cầu thực hành độc lập"></div><div class="field"><label>Hạn hoàn thành</label><input type="date" name="due_date"></div><div class="field full"><label>Ghi chú</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Phân công năng lực</button></div></form>`}
function openCompetencyAssign(data,memberRef=''){openDrawer('Phân công năng lực','competency',competencyAssignFormHtml(data,memberRef),{layout:'modal'});const f=$('#competencyAssignForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api('competency/assignments',{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã phân công năng lực');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}}}
function competencyAssessmentFormHtml(a,data){return `<form id="competencyAssessmentForm"><div class="competency-form-context"><strong>${esc(a.code)} · ${esc(a.title)}</strong><span>${esc(a.user_name||'')}</span></div><div class="form-grid"><div class="field"><label>Ngày đánh giá</label><input type="date" name="assessed_at" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Phương pháp đánh giá</label><select name="method">${Object.entries(data.assessmentMethods||{}).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Kết quả *</label><select name="result" required><option value="competent">Đạt năng lực</option><option value="needs_training">Cần đào tạo bổ sung</option><option value="not_competent">Chưa đạt năng lực</option></select></div><div class="field"><label>Điểm (nếu áp dụng)</label><input type="number" min="0" max="100" name="score"></div><div class="field"><label>Đánh giá lại vào</label><input type="date" name="next_due"></div><div class="field"><label>Liên kết bằng chứng</label><input name="evidence_url" placeholder="Google Drive / hồ sơ liên quan"></div><div class="field full"><label>Nhận xét</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu đánh giá</button></div></form>`}
function competencyAuthorizationFormHtml(a){const auth=a.authorization||{};return `<form id="competencyAuthorizationForm"><div class="competency-form-context"><strong>${esc(a.code)} · ${esc(a.title)}</strong><span>Chỉ cấp ủy quyền khi đánh giá năng lực đạt và còn hiệu lực.</span></div><div class="form-grid"><div class="field full"><label>Phạm vi được ủy quyền</label><textarea name="scope">${esc(auth.scope||a.title||'')}</textarea></div><div class="field"><label>Hiệu lực từ</label><input type="date" name="valid_from" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Hiệu lực đến</label><input type="date" name="valid_until"></div><div class="field full"><label>Ghi chú</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary" name="action" value="grant">Cấp / gia hạn ủy quyền</button>${auth.effective_status==='active'?'<button class="btn warning" name="action" value="suspend">Tạm dừng</button><button class="btn danger" name="action" value="revoke">Thu hồi</button>':''}</div></form>`}
function competencyTrainingFormHtml(a){return `<form id="competencyTrainingForm"><div class="competency-form-context"><strong>${esc(a.code)} · ${esc(a.title)}</strong>${a.required_training?`<span>Đào tạo gợi ý: ${esc(a.required_training)}</span>`:''}</div><div class="form-grid"><div class="field full"><label>Nội dung đào tạo *</label><input name="title" required value="${esc(a.required_training||'')}"></div><div class="field"><label>Đơn vị/giảng viên</label><input name="provider"></div><div class="field"><label>Hạn hoàn thành</label><input type="date" name="required_by"></div><div class="field"><label>Trạng thái</label><select name="status"><option value="required">Cần hoàn thành</option><option value="in_progress">Đang học/đào tạo</option><option value="completed">Đã hoàn thành</option></select></div><div class="field"><label>Ngày hoàn thành</label><input type="date" name="completed_at"></div><div class="field full"><label>Liên kết chứng nhận/hồ sơ</label><input name="evidence_url"></div><div class="field full"><label>Ghi chú</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu đào tạo</button></div></form>`}
function competencyAssignmentHtml(a,canManage){const as=a.assessment,au=a.authorization,tr=a.training||[];const alerts=[];if(a.alerts?.assessmentDue)alerts.push('<span class="competency-alert danger">Đến hạn đánh giá</span>');else if(a.alerts?.assessmentSoon)alerts.push('<span class="competency-alert warning">Sắp đến hạn đánh giá</span>');if(a.alerts?.authorizationExpired)alerts.push('<span class="competency-alert danger">Ủy quyền hết hạn</span>');else if(a.alerts?.authorizationSoon)alerts.push('<span class="competency-alert warning">Ủy quyền sắp hết hạn</span>');if(a.alerts?.trainingDue)alerts.push('<span class="competency-alert warning">Đào tạo quá hạn</span>');return `<article class="competency-assignment-card"><div class="competency-assignment-head"><div><span class="code">${esc(a.code)}</span><h4>${esc(a.title)}</h4><small>${esc(competencyItemTypeLabels[a.item_type]||a.item_type)} · ISO ${esc(a.iso_clause||'—')}</small></div><span class="badge ${competencyStatusClass(a.matrix_status)}">${esc(competencyStatusLabels[a.matrix_status]||a.matrix_status)}</span></div>${alerts.length?`<div class="competency-alerts">${alerts.join('')}</div>`:''}<div class="competency-assignment-grid"><div><small>Đánh giá gần nhất</small><strong>${as?fmtDate(as.assessed_at):'Chưa đánh giá'}</strong><span>${as?esc(as.result==='competent'?'Đạt':as.result==='needs_training'?'Cần đào tạo':'Chưa đạt'):'—'}${as?.next_due?' · Đánh giá lại '+fmtDate(as.next_due):''}</span></div><div><small>Ủy quyền</small><strong>${au?esc(au.effective_status==='active'?'Đang hiệu lực':au.effective_status==='expired'?'Hết hạn':au.status==='suspended'?'Tạm dừng':'Đã thu hồi'):'Chưa cấp'}</strong><span>${au?.valid_until?'Đến '+fmtDate(au.valid_until):'—'}</span></div><div><small>Đào tạo</small><strong>${tr.filter(x=>x.status==='completed').length}/${tr.length||0} hoàn thành</strong><span>${esc(a.required_training||'Chưa quy định')}</span></div></div>${canManage?`<div class="competency-actions"><button class="btn small" data-comp-assess="${a.id}">Đánh giá</button><button class="btn small" data-comp-auth="${a.id}">Ủy quyền</button><button class="btn small" data-comp-training="${a.id}">Đào tạo</button><button class="btn small danger" data-comp-remove="${a.id}">Bỏ phân công</button></div>`:''}</article>`}
function openCompetencyMember(data,ref){const row=(data.matrix||[]).find(x=>x.member?.ref===ref);if(!row)return;const m=row.member,s=row.summary||{},cards=(row.assignments||[]).map(x=>competencyAssignmentHtml(x,data.canManage)).join('')||'<div class="note">Chưa được phân công nội dung năng lực.</div>';openDrawer(m.name,'competency',`<div class="competency-member"><div class="team-member-summary"><div class="team-avatar large">${esc((m.name||'N').charAt(0).toUpperCase())}</div><div><h3>${esc(m.name)}</h3><p>${esc(m.roleLabel||'')} · ${m.isActive?'Đang hoạt động':'Ngừng hoạt động'}</p></div>${data.canManage?'<button class="btn primary small" id="assignCompetencyMember">＋ Phân công năng lực</button>':''}</div><div class="competency-member-kpis"><div><small>Nội dung cần đáp ứng</small><strong>${s.total||0}</strong></div><div><small>Đạt năng lực</small><strong>${s.competent||0}</strong></div><div><small>Tỷ lệ đạt</small><strong>${s.competencyPct||0}%</strong></div><div><small>Đến hạn đánh giá</small><strong>${s.assessmentDue||0}</strong></div><div><small>Cảnh báo ủy quyền</small><strong>${s.authorizationAlerts||0}</strong></div></div><div class="competency-assignment-list">${cards}</div></div>`,{layout:'modal'});$('#assignCompetencyMember')?.addEventListener('click',()=>openCompetencyAssign(data,ref));$$('[data-comp-assess]').forEach(b=>b.onclick=()=>{const a=row.assignments.find(x=>x.id===+b.dataset.compAssess);openDrawer('Đánh giá năng lực','competency',competencyAssessmentFormHtml({...a,user_name:m.name},data),{layout:'modal'});const f=$('#competencyAssessmentForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api(`competency/assignments/${a.id}/assessment`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã lưu đánh giá năng lực');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}}});$$('[data-comp-auth]').forEach(b=>b.onclick=()=>{const a=row.assignments.find(x=>x.id===+b.dataset.compAuth);openDrawer('Phạm vi ủy quyền','competency',competencyAuthorizationFormHtml(a),{layout:'modal'});const f=$('#competencyAuthorizationForm');$('[data-close]',f).onclick=closeDrawer;f.addEventListener('submit',async e=>{e.preventDefault();const submit=e.submitter;const d=Object.fromEntries(new FormData(f).entries());d.action=submit?.value||'grant';try{await api(`competency/assignments/${a.id}/authorization`,{method:'POST',json:d});toast(d.action==='grant'?'Đã cập nhật ủy quyền':d.action==='suspend'?'Đã tạm dừng ủy quyền':'Đã thu hồi ủy quyền');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}})});$$('[data-comp-training]').forEach(b=>b.onclick=()=>{const a=row.assignments.find(x=>x.id===+b.dataset.compTraining);openDrawer('Đào tạo bắt buộc','competency',competencyTrainingFormHtml(a),{layout:'modal'});const f=$('#competencyTrainingForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api(`competency/assignments/${a.id}/training`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã cập nhật đào tạo');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}}});$$('[data-comp-remove]').forEach(b=>b.onclick=async()=>{if(!confirm('Bỏ nội dung năng lực này khỏi nhân viên?'))return;try{await api(`competency/assignments/${b.dataset.compRemove}`,{method:'DELETE'});toast('Đã bỏ phân công năng lực');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}})}
async function renderCompetency(){const data=await api('competency/overview'),sum=data.summary||{};const matrix=(data.matrix||[]).map(x=>`<tr data-comp-member="${esc(x.member.ref)}"><td><div class="team-person"><span class="team-avatar">${esc((x.member.name||'N').charAt(0).toUpperCase())}</span><div><strong>${esc(x.member.name)}</strong><small>${esc(x.member.roleLabel||'')}${x.member.isActive?'':' · Ngừng hoạt động'}</small></div></div></td><td>${x.summary.total||0}</td><td><div class="team-progress-cell"><div class="progress"><span style="width:${Math.max(0,Math.min(100,x.summary.competencyPct||0))}%"></span></div><b>${x.summary.competencyPct||0}%</b></div></td><td><strong class="${x.summary.assessmentDue?'text-danger':''}">${x.summary.assessmentDue||0}</strong></td><td><strong class="${x.summary.authorizationAlerts?'text-warning':''}">${x.summary.authorizationAlerts||0}</strong></td><td>${x.summary.trainingDue||0}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Chưa có nhân sự Khoa Xét nghiệm.</td></tr>';const catalog=(data.items||[]).map(i=>`<tr data-comp-item="${i.id}"><td><span class="code">${esc(i.code)}</span></td><td><strong>${esc(i.title)}</strong><div class="meta">${esc(i.description||'')}</div></td><td>${esc(competencyItemTypeLabels[i.item_type]||i.item_type)}</td><td>${esc(i.iso_clause||'—')}</td><td>${i.assessment_frequency_months} tháng</td><td>${i.authorization_valid_months} tháng</td><td>${i.is_active?'<span class="badge active">Đang dùng</span>':'<span class="badge closed">Ngừng dùng</span>'}</td></tr>`).join('');$('#content').innerHTML=`<section class="card module-hero competency-hero"><div><span class="eyebrow">ISO 15189 · NHÂN SỰ</span><h2>Năng lực & ủy quyền</h2><p>Theo dõi yêu cầu năng lực, đánh giá định kỳ, đào tạo bắt buộc và phạm vi được phép thực hiện của từng nhân viên.</p></div>${data.canManage?'<div class="hero-actions"><button class="btn" id="newCompetencyItem">＋ Tiêu chí năng lực</button><button class="btn primary" id="assignCompetency">＋ Phân công</button></div>':''}</section><section class="competency-kpis"><div class="card"><small>Phân công năng lực</small><strong>${sum.assignments||0}</strong><span>Đang theo dõi</span></div><div class="card good"><small>Đạt năng lực</small><strong>${sum.competencyPct||0}%</strong><span>${sum.competent||0}/${sum.assignments||0} nội dung</span></div><div class="card warning"><small>Đến hạn đánh giá</small><strong>${sum.assessmentDue||0}</strong><span>Cần đánh giá/đánh giá lại</span></div><div class="card warning"><small>Ủy quyền sắp hết hạn</small><strong>${sum.authorizationExpiring||0}</strong><span>Trong 30 ngày</span></div><div class="card danger"><small>Ủy quyền hết hạn</small><strong>${sum.authorizationExpired||0}</strong><span>Không nên thực hiện độc lập</span></div></section><section class="card panel"><div class="panel-head"><div><h3>Ma trận năng lực nhân viên</h3><div class="panel-sub">Bấm vào từng nhân viên để xem chi tiết đánh giá, đào tạo và ủy quyền.</div></div></div><div class="table-card"><table class="data-table competency-matrix"><thead><tr><th>NHÂN SỰ</th><th>NỘI DUNG</th><th>TỶ LỆ ĐẠT</th><th>ĐẾN HẠN ĐÁNH GIÁ</th><th>CẢNH BÁO ỦY QUYỀN</th><th>ĐÀO TẠO QUÁ HẠN</th></tr></thead><tbody>${matrix}</tbody></table></div></section><section class="card panel"><div class="panel-head"><div><h3>Danh mục năng lực</h3><div class="panel-sub">Chu kỳ đánh giá và thời hạn ủy quyền là thông số nội bộ, có thể điều chỉnh theo quy trình của Khoa Xét nghiệm.</div></div></div><div class="table-card"><table class="data-table"><thead><tr><th>MÃ</th><th>NỘI DUNG</th><th>NHÓM</th><th>ISO</th><th>ĐÁNH GIÁ</th><th>ỦY QUYỀN</th><th>TRẠNG THÁI</th></tr></thead><tbody>${catalog}</tbody></table></div></section>`;$('#newCompetencyItem')?.addEventListener('click',()=>openCompetencyItemForm(data));$('#assignCompetency')?.addEventListener('click',()=>openCompetencyAssign(data));$$('[data-comp-member]').forEach(r=>r.onclick=()=>openCompetencyMember(data,r.dataset.compMember));if(data.canManage)$$('[data-comp-item]').forEach(r=>r.onclick=()=>{const item=(data.items||[]).find(x=>x.id===+r.dataset.compItem);if(item)openCompetencyItemForm(data,item)})}

async function renderImplementation(){const data=await api('knowledge/implementation');if(state.module!=='implementation')return;const plan=data.plan||{};const ps=plan.progress_summary||{};const wizard=(plan.wizard||[]).map(x=>`<div class="wizard-step"><b>${x.step}</b><div><strong>${esc(x.title)}</strong><small>${esc(x.deliverable||'')}</small></div></div>`).join('');const tasksByCode=Object.fromEntries((data.tasks||[]).map(t=>[t.code,t]));const cards=(plan.consultant_plan||[]).map((x,i)=>{const code=`ISO-PLAN-${String(i+1).padStart(2,'0')}`,t=tasksByCode[code];const status=t?.status||x.status||'review';const statusText=t?(statusLabels[t.status]||t.status):(x.status==='done'?'Đã hoàn thành':x.status==='in_progress'?'Đang thực hiện':x.status==='open'?'Chưa hoàn thành':'Đang xem xét');const titleLine=String(x.content||'').split(String.fromCharCode(10))[0]||`Đầu việc ${i+1}`;return `<article class="plan-card"><div class="plan-head"><span class="code">${code}</span><span class="badge ${esc(status)}">${esc(statusText)}</span></div><h4>${esc(titleLine)}</h4><p>${esc(x.content||'')}</p><div class="plan-meta"><span><strong>Thực hiện:</strong> ${esc((x.assignees||[]).join(', ')||'—')}</span><span><strong>Giám sát:</strong> ${esc(x.supervisor||'—')}</span><span><strong>Hạn nguồn:</strong> ${fmtDate(x.due_date)}</span><span><strong>Nộp tư vấn:</strong> ${fmtDate(x.consultant_due)}</span></div>${t?`<button class="btn small" data-record="${t.id}">Mở công việc · ${t.progress||0}%</button>`:''}</article>`}).join('');const summary=summaryCardsHtml(ps.summary_cards||[],'implementation-overview-cards');const progressRows=progressGroupRows(ps.current_groups||[]);const actionList=(ps.actions||[]).map(x=>`<li>${esc(x)}</li>`).join('');const difficultyList=(ps.difficulties||[]).map(x=>`<li>${esc(x)}</li>`).join('');const checklist=(plan.implementation_checklist||[]).map(x=>{const due=x.due_date||'';const overdue=due&&new Date(due+'T23:59:59')<new Date()&&!['done','completed','closed'].includes(x.status);const st=x.status_label||({not_started:'Chưa bắt đầu',in_progress:'Đang thực hiện',review:'Chờ rà soát',done:'Hoàn thành',blocked:'Đang vướng'}[x.status]||x.status||'Chưa bắt đầu');return `<tr class="${overdue?'row-overdue':''}"><td><b>${esc(x.seq)}</b></td><td><span class="priority-chip ${esc(String(x.priority||'').toLowerCase())}">${esc(x.priority||'')}</span></td><td>${esc(x.phase||'')}</td><td><strong>${esc(x.task||'')}</strong><small class="source-path">ISO ${esc(x.clauses||'—')}</small></td><td>${esc(x.responsible||'—')}</td><td>${esc(x.accountable||'—')}</td><td>${esc(x.consulted_informed||'—')}</td><td><strong>${fmtDate(due)}</strong>${overdue?'<small class="text-danger">Quá mốc đề xuất</small>':''}</td><td><span class="badge ${esc(x.status||'new')}">${esc(st)}</span></td><td>${esc(x.dependencies||'—')}</td><td>${esc(x.evidence||'—')}</td><td>${esc(x.acceptance_criteria||'—')}</td><td>${esc(x.note||'')}</td></tr>`}).join('');const raci=(plan.responsibility_matrix||[]).map(x=>`<tr><td><strong>${esc(x.workstream||'')}</strong></td><td>${esc(x.responsible||'')}</td><td>${esc(x.accountable||'')}</td><td>${esc(x.consulted||'')}</td><td>${esc(x.informed||'')}</td><td>${esc(x.cadence||'')}</td></tr>`).join('');$('#content').innerHTML=`<div class="module-clarity mc-implementation"><section class="mc-intro"><div><span class="mc-eyebrow">KẾ HOẠCH TRIỂN KHAI</span><h2>${esc(plan.title||'Triển khai TCVN ISO 15189:2025')}</h2><p>Theo dõi công việc theo giai đoạn, đầu mối phụ trách và mốc kế hoạch.</p></div><div class="mc-project-state"><strong>${data.project?'Đã khởi tạo dự án':'Chưa khởi tạo dự án'}</strong><span>${data.tasks?.length||0}/${(plan.consultant_plan||[]).length} công việc nguồn đã đồng bộ</span></div></section>${plan.planning_note?`<details class="mc-source-note"><summary>Phạm vi và cơ sở kế hoạch</summary><p>${esc(plan.planning_note)}</p></details>`:''}<section class="mc-panel"><div class="mc-section-head"><div><h3>Công việc triển khai</h3><p>Mốc đề xuất cần được đối chiếu với lịch đã phê duyệt. Mở từng việc để xem phân công, phụ thuộc và đầu ra.</p></div><div class="mc-intro-actions"><button class="btn small" id="printImplChecklist">In A4</button><button class="btn small" id="pdfImplChecklist">PDF A4</button><button class="btn small" id="docxImplChecklist">DOCX A4</button></div></div><div class="mc-plan-filters"><div class="mc-search"><label for="implLocalSearch">Tìm công việc</label><input id="implLocalSearch" type="search" placeholder="Tên công việc, đầu mối hoặc điều khoản…"></div><div><label for="implPhaseFilter">Giai đoạn</label><select id="implPhaseFilter"><option value="">Tất cả giai đoạn</option>${[...new Set((plan.implementation_checklist||[]).map(x=>x.phase).filter(Boolean))].map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></div><div><label for="implPriorityFilter">Ưu tiên</label><select id="implPriorityFilter"><option value="">Tất cả ưu tiên</option><option>P0</option><option>P1</option><option>P2</option></select></div><div><label for="implStatusFilter">Trạng thái</label><select id="implStatusFilter"><option value="">Tất cả trạng thái</option><option value="past_due">Quá mốc đề xuất</option>${[...new Set((plan.implementation_checklist||[]).map(x=>x.status||'not_started'))].map(v=>`<option value="${esc(v)}">${esc(implementationStateLabel({status:v}))}</option>`).join('')}</select></div></div><div class="mc-plan-legend">P0 · Nền tảng / an toàn / pháp lý <span> P1 · Cần hoàn thiện trước đánh giá sẵn sàng</span><span> P2 · Tối ưu hóa</span></div><p id="implResultCount" class="mc-result-count" aria-live="polite"></p><div id="implWorkList" class="mc-work-list"></div><details class="mc-full-table"><summary>Xem bảng đầy đủ · ${plan.implementation_checklist?.length||0} công việc · Bản dùng để xuất</summary><p class="mc-result-count">Bản xuất gồm toàn bộ kế hoạch, không giới hạn theo bộ lọc trên màn hình.</p><div class="table-card wide-table" id="implementationChecklistExport"><table class="data-table"><thead><tr><th>STT</th><th>ƯU TIÊN</th><th>GIAI ĐOẠN</th><th>CÔNG VIỆC / ĐIỀU KHOẢN</th><th>R · THỰC HIỆN</th><th>A · CHỊU TRÁCH NHIỆM</th><th>C/I · PHỐI HỢP/THÔNG TIN</th><th>HẠN</th><th>TRẠNG THÁI</th><th>PHỤ THUỘC</th><th>BẰNG CHỨNG HOÀN THÀNH</th><th>TIÊU CHÍ HOÀN THÀNH</th><th>GHI CHÚ</th></tr></thead><tbody>${checklist}</tbody></table></div></details></section>${summary?`<details class="mc-panel mc-secondary"><summary>Khối lượng tài liệu đang triển khai <small>Ngày báo cáo ${fmtDate(ps.report_date||'')}</small></summary><div class="mc-secondary-body">${summary}</div></details>`:''}<details class="mc-panel mc-secondary"><summary>Trình tự triển khai <small>${plan.wizard?.length||0} bước và đầu ra</small></summary><div class="mc-secondary-body"><div class="wizard-grid">${wizard}</div></div></details><details class="mc-panel mc-secondary"><summary>Phân công trách nhiệm <small>Thực hiện · Chịu trách nhiệm · Tham vấn · Thông tin</small></summary><div class="mc-secondary-body"><div class="table-card" id="raciExport"><table class="data-table"><thead><tr><th>NHÓM CÔNG VIỆC</th><th>TRỰC TIẾP THỰC HIỆN</th><th>CHỊU TRÁCH NHIỆM</th><th>THAM VẤN</th><th>ĐƯỢC THÔNG TIN</th><th>NHỊP THEO DÕI</th></tr></thead><tbody>${raci}</tbody></table></div></div></details>${progressRows?`<details class="mc-panel mc-secondary"><summary>Nhóm tài liệu đang theo dõi thực tế</summary><div class="mc-secondary-body"><div class="table-card"><table class="data-table"><thead><tr><th>NHÓM TÀI LIỆU</th><th>NGÀY GIAO</th><th>HẠN SAU RÀ SOÁT</th><th>TRẠNG THÁI</th><th>RÀ SOÁT</th><th>GHI CHÚ</th></tr></thead><tbody>${progressRows}</tbody></table></div></div></details>`:''}<section class="mc-panel"><div class="mc-section-head"><div><h3>Đầu việc nguồn / tư vấn</h3><p>Phân công và thời hạn nguồn được giữ để đối chiếu tiến độ thực tế.</p></div>${data.canSeed?'<button class="btn primary small" id="seedPlan">Khởi tạo/cập nhật dự án & công việc</button>':''}</div><details class="mc-source-tasks"><summary>Xem ${plan.consultant_plan?.length||0} đầu việc nguồn và công việc đã đồng bộ</summary><div class="plan-grid">${cards}</div></details></section><section class="implementation-notes-grid">${difficultyList?`<div class="mc-panel"><h3>Khó khăn, vướng mắc</h3><ul class="bulleted-list">${difficultyList}</ul></div>`:''}${actionList?`<div class="mc-panel"><h3>Hướng xử lý và kiểm soát tiến độ</h3><ul class="bulleted-list">${actionList}</ul></div>`:''}</section></div>`;$('#seedPlan')?.addEventListener('click',async()=>{try{const r=await api('knowledge/implementation/seed',{method:'POST'});toast(`Đã đồng bộ kế hoạch · thêm ${r.tasksCreated||0} công việc`);await refreshBootstrapLight();await renderImplementation()}catch(err){toast(err.message,'err')}});$$('[data-record]').forEach(x=>x.onclick=()=>openRecord(+x.dataset.record));$('#printImplChecklist')?.addEventListener('click',()=>{auditUiEvent('print_a4',{module:'implementation',title:'Bảng kiểm triển khai ISO'});printElementA4($('#implementationChecklistExport'))});$('#pdfImplChecklist')?.addEventListener('click',()=>exportElementPdf($('#implementationChecklistExport'),'Ke-hoach-trien-khai-ISO-15189.pdf',{action:'report_export',module:'implementation',title:'Bảng kiểm triển khai ISO'}));$('#docxImplChecklist')?.addEventListener('click',()=>exportElementDocx($('#implementationChecklistExport'),'Ke-hoach-trien-khai-ISO-15189.docx','Kế hoạch triển khai TCVN ISO 15189:2025',{action:'report_export',module:'implementation',title:'Bảng kiểm triển khai ISO'}));const drawWork=()=>{const q=clarityText($('#implLocalSearch').value.trim()),phase=$('#implPhaseFilter').value,priority=$('#implPriorityFilter').value,status=$('#implStatusFilter').value;const rows=(plan.implementation_checklist||[]).filter(x=>(!phase||x.phase===phase)&&(!priority||x.priority===priority)&&(!status||(status==='past_due'?implementationPastDue(x):(x.status||'not_started')===status))&&clarityText([x.task,x.responsible,x.accountable,x.clauses].join(' ')).includes(q));$('#implWorkList').innerHTML=rows.map(clarityImplementationItem).join('')||'<div class="mc-empty">Không có công việc phù hợp. Hãy điều chỉnh bộ lọc.</div>';$('#implResultCount').textContent=`${rows.length}/${plan.implementation_checklist?.length||0} công việc · Mốc kế hoạch đề xuất`};$('#implLocalSearch').addEventListener('input',drawWork);['implPhaseFilter','implPriorityFilter','implStatusFilter'].forEach(id=>$('#'+id).addEventListener('change',drawWork));drawWork()}
