 if(state.paTab==='timeline')body=`<div class="card"><h3>Lịch sử sự kiện quá trình</h3><div class="pa-timeline">${(d.events||[]).map(x=>`<div><i></i><span><strong>${esc(x.summary)}</strong><small>${paDateTime(x.occurred_at)} · ${esc(x.actor_name||'Hệ thống')} · ${esc(paStatus(x.status))}</small></span></div>`).join('')||'<p class="empty">Chưa có sự kiện.</p>'}</div></div>`;
 $('#content').innerHTML=`<section class="module-simple-head"><div><h2>Bảo đảm quá trình xét nghiệm</h2></div></section><div class="pa-kpis">${kpis.map(([l,v])=>`<div><span>${esc(l)}</span><strong>${v}</strong></div>`).join('')}</div>${paTabs()}<div class="pa-body">${body}</div>`;
 $$('[data-pa-tab]').forEach(b=>b.onclick=()=>{state.paTab=b.dataset.paTab;renderProcessAssurance()});
 const submit=(id,path,method='POST',map=x=>x)=>{$('#'+id)?.addEventListener('submit',async e=>{e.preventDefault();try{const x=map(paFormPayload(e.currentTarget));await api(path(x),{method,json:x});toast('Đã lưu');await renderProcessAssurance()}catch(err){toast(err.message,'err')}})};
