 $$('[data-pa-exception]').forEach(b=>b.onclick=async()=>{const reason=prompt('Mô tả mẫu không phù hợp / lý do:','');if(!reason)return;const decision=confirm('OK = TỪ CHỐI mẫu; Cancel = CHẤP NHẬN NGOẠI LỆ sau đánh giá nguy cơ.')?'reject':'accept_exception';let risk='';if(decision==='accept_exception')risk=prompt('Đánh giá nguy cơ khi chấp nhận ngoại lệ:','')||'';try{await api(`process-assurance/samples/${b.dataset.paException}/exceptions`,{method:'POST',json:{exception_type:'other',decision,reason,risk_assessment:risk}});toast('Đã ghi nhận quyết định mẫu');await renderProcessAssurance()}catch(e){toast(e.message,'err')}});
 $$('[data-pa-notify-critical]').forEach(b=>b.onclick=async()=>{const target=prompt('Người/đơn vị đã nhận thông báo:','');if(target===null)return;const readback=prompt('Nội dung đọc lại xác nhận (nếu có):','')||'';try{await api(`process-assurance/critical-results/${b.dataset.paNotifyCritical}`,{method:'PATCH',json:{mark_notified:1,notification_target:target,readback_text:readback,status:'acknowledged'}});toast('Đã ghi thời điểm thông báo');await renderProcessAssurance()}catch(e){toast(e.message,'err')}});
 $$('[data-pa-close-complaint]').forEach(b=>b.onclick=async()=>{const investigation=prompt('Kết quả điều tra khiếu nại:','');if(!investigation)return;const response=prompt('Nội dung phản hồi/kết luận:','')||'';const independent=confirm('Xác nhận người giải quyết độc lập với vấn đề khiếu nại?');try{await api(`process-assurance/complaints/${b.dataset.paCloseComplaint}`,{method:'PATCH',json:{investigation,response_text:response,independence_confirmed:independent?1:0,responded_at:new Date().toLocaleString('sv-SE').slice(0,16),status:'closed'}});toast('Đã hoàn tất khiếu nại');await renderProcessAssurance()}catch(e){toast(e.message,'err')}});
